/* Musée de la République de Sovarka (Novomirsk) — présentations fixes de la guide Ouliana Historiskaïa.
 * Textes validés par Fred le 11/11/2026 (GAME-DESIGN-NOVOMIRSK.md), traduits une fois par langue et stockés ici :
 * resservis gratuitement, sans appel serveur ni IA. Le français est la référence et la langue de repli.
 * Paragraphes séparés par une ligne vide.
 */
(function(global){
'use strict';
const texts={
  "fr": {
    "q_title": "Questions à la guide",
    "q_intro": "Pour 1 PA, Ouliana répond à trois questions dans cette salle (une fois par jour).",
    "q_open": "Poser des questions (1 PA)",
    "q_placeholder": "Votre question historique…",
    "q_ask": "Demander ({n} restantes)",
    "q_you": "Vous",
    "q_wait": "Ouliana réfléchit…",
    "q_done": "Ouliana vous invite poliment à poursuivre la visite.",
    "q_error": "Ouliana ne peut pas répondre pour le moment. Aucune question n’a été comptée.",
    "q_r_pas_sur_place": "Il faut se trouver dans une salle du musée.",
    "q_r_questions_epuisees": "Vous avez déjà posé vos trois questions dans cette salle aujourd’hui.",
    "q_r_dialogue_non_ouvert": "Ouvrez d’abord les questions (1 PA).",
    "q_r_pa_insuffisants": "Vous n’avez pas assez de PA.",
    "q_r_autre": "Le serveur n’a pas confirmé. Rien n’a été prélevé.",
    "tGuide": "Ouliana Historiskaïa, guide officielle",
    "listen": "Écouter la guide",
    "f_hall": "Bonjour et bienvenue au Musée de la République de Sovarka, camarades. Je suis Ouliana Historiskaïa, guide officielle du musée, au service de l'histoire. De l'histoire officielle, s'entend : c'est la seule qui ait été conservée.\n\nLe parcours vous mènera des grands présidents aux grands partis, de nos héros militaires à nos artistes, sans oublier le tractorisme, nos sportifs et nos grandes crises. Je vous conseille de suivre l'ordre de la visite. Rien n'est interdit, bien sûr. C'est simplement conseillé, très fortement.\n\nLa photographie est autorisée partout, sauf là où elle ne l'est pas. Les gardiens vous le signaleront.\n\nAvez-vous des questions ? Uniquement historiques, je vous prie.",
    "f_salle_presidents": "Bienvenue dans la Salle des présidents, camarades visiteurs. Approchez, approchez.\n\nVoici les cinq grands guides qui ont conduit Sovarka sur le chemin du progrès.\n\nÀ gauche, le camarade Arkadi Ivanovitch Zolotov, premier Président de notre République. C'est lui qui inaugura le Palais présidentiel. Pendant trente ans, il honora de sa présence chaque ouverture d'usine, de pont et d'école du pays. Aucun président n'a coupé autant de rubans au service du peuple.\n\nVient ensuite Taras Sergueïevitch Belov. On lui doit le célèbre décret sur l'heure du thé, toujours en vigueur aujourd'hui. Un texte d'une rare stabilité : jamais contesté, jamais abrogé.\n\nLe camarade Boris Nikolaïevitch Gromov fut réélu sept fois. Le peuple l'aimait tant qu'il n'eut même pas besoin de se porter candidat.\n\nLui succéda Vladimir Petrovitch Lebedev. Vous remarquez sans doute la ressemblance avec son prédécesseur… Elle est en effet troublante. Le peuple, qui avait tant aimé le camarade Gromov, reporta naturellement sur lui une grande partie de son affection. Lebedev fut aussi un grand défenseur du dialogue entre les institutions : sa correspondance avec le Conseil du Peuple est conservée aux archives… en trois exemplaires.\n\nEnfin, Guennadi Andreïevitch Sokolov. Oui, la même mâchoire, le même regard. Les électeurs y virent le signe d'une admirable continuité. Il offrit au Palais son samovar d'argent, qui réchauffe encore aujourd'hui les plus hautes délibérations de l'État.\n\nIl n'existe, bien entendu, aucun lien de parenté entre ces trois grands hommes. Les noms de famille le prouvent. Les registres de l'état civil de l'époque ont malheureusement été détruits lors de l'incendie des archives, mais l'historiographie officielle est formelle.\n\nEt ces deux cadres vides, me direz-vous ? Ils attendent les futurs dirigeants que le peuple aura la sagesse de choisir. Qui sait… peut-être l'un d'entre vous ?\n\nAvez-vous des questions ? Je vous rappelle que je ne réponds qu'aux questions historiques.",
    "f_salle_politiques": "Voici la Salle des partis politiques victorieux. Admirez ces bannières : chacune porte le visage d'un président élu, et derrière chaque visage, le grand parti qui l'a porté au pouvoir.\n\nCar oui, un Président n'est que l'humble représentant du parti qui l'a porté au pouvoir, et le parti n'est lui-même que la modeste structure qui représente le peuple souverain.\n\nCommençons par le Parti des Précurseurs Politiques. Ce sont eux qui ont conduit notre nation hors des ténèbres tsaristes, vers la vie hautement démocratique que nous connaissons aujourd'hui. Hautement démocratique, oui. Je pèse mes mots. Le Parti a donné à Sovarka ses deux premiers présidents, le camarade Zolotov et le camarade Belov. Dans la vitrine, vous verrez la première carte du Parti, la plume qui signa la Constitution, et une photographie du premier scrutin libre. On y distingue très bien l'urne, et le représentant du Parti qui en assurait la protection.\n\nAu centre, le Parti du Prolétariat Heureux, celui du camarade Gromov. Son programme tenait en une phrase : le prolétariat est heureux. Les études de l'époque l'ont confirmé à cent pour cent. Le Parti s'est ensuite dissous de lui-même, sa mission étant accomplie.\n\nEnfin, le Parti du Progrès Nostalgique, qui a donné au pays les camarades Lebedev et Sokolov. Sa devise : « Avancer vers le passé sans jamais reculer ». Certains pays appellent ceci le \"moonwalk\", d'autres le tango Estadien. Ses adversaires, des traîtres à la nation qu'il a fallu rééduquer, disaient qu'il n'avait rien de nouveau à proposer. C'était justement tout son programme.\n\nVous remarquerez peut-être que les camarades Lebedev et Sokolov ressemblent beaucoup au camarade Gromov, alors qu'ils appartenaient à un autre parti. C'est la preuve que chez nous, le pluralisme n'empêche pas la continuité.\n\nCes trois grands partis ont un point commun : ils ont remporté toutes les élections auxquelles ils se sont présentés. Les autres partis ? Ils n'étaient pas prêts. Ils le sont peut-être aujourd'hui… Les registres d'inscription se trouvent à la mairie.\n\nAvez-vous des questions ? Uniquement historiques, je vous prie.",
    "f_salle_honneur_militaire_nationale": "Approchez, camarades. Vous entrez dans la Salle des honneurs militaires. Ici, chaque médaille raconte une victoire, et chaque victoire a été dûment homologuée par le ministère de la Défense de la Patrie.\n\nDans la grande vitrine, l'uniforme d'apparat du premier commandant de l'Armée populaire. Il compte quarante-sept médailles : près de quinze kilos de métal. Les historiens s'accordent à dire qu'il les a toutes méritées, y compris celles qu'il s'est remises lui-même. Lors de l'attentat de Krasnov, elles lui ont sauvé la vie : la balle, tirée en plein cœur, s'est écrasée contre elles, ne lui causant qu'un léger hématome.\n\nSur ce mur, la carte de la Grande Défense du Nord. Nos soldats y ont tenu leurs positions pendant onze hivers, face à un ennemi qui, faute de documents, reste à ce jour inconnu. Il n'est jamais venu : la preuve que la défense fut parfaite. Notez d'ailleurs que Sovarka n'a jamais été conquise. C'est l'une de ses plus grandes fiertés.\n\nCe casque cabossé appartenait au soldat Piotr Neviyev, héros de la nation. Il fut le premier à franchir le fleuve gelé lors de la marche de 1924. Le second fut son commandant, qui tenait à vérifier que la glace était solide.\n\nRemarquez enfin le registre d'honneur des conscrits. Chaque citoyen appelé sous les drapeaux y inscrit son nom avec fierté. Ceux qui ne s'y sont pas inscrits figurent dans un autre registre, conservé ailleurs.\n\nAvez-vous des questions ? Uniquement historiques, je vous prie.",
    "f_salle_organisations": "Bienvenue dans la Salle du tractorisme, camarades. Vous êtes ici au cœur de l'âme de Sovarka.\n\nLe tractorisme n'est pas une superstition : c'est une religion scientifique. Elle enseigne que le Tracteur Collectif laboure les champs comme il laboure les consciences, en ligne droite et sans jamais reculer. Et dans une conscience bien labourée, les graines de la liberté et de l'émancipation finissent toujours par germer.\n\nDans cette vitrine, la Sainte Bougie, une bougie d'allumage retrouvée intacte dans le premier tracteur du kolkhoze de Krasnov. On lui attribue de nombreux miracles. Le plus connu est celui de l'hiver 1931 : le tracteur a démarré du premier coup.\n\nSur ce mur, les Dix Commandements de l'Entretien. Le premier : « Tu vidangeras tous les cinq mille kilomètres. » Le dixième : « Tu ne convoiteras pas le tracteur de ton voisin, car tous les tracteurs appartiennent au peuple. »\n\nRemarquez ces vêtements liturgiques : la salopette bleue des grandes fêtes et le bleu de travail des jours ordinaires. Le Camarade Pontife Tractorenko les porte encore lors de la Bénédiction des Moteurs, chaque printemps, à la Grande Église.\n\nL'État et le tractorisme sont parfaitement séparés, bien entendu. Il arrive simplement qu'ils pensent la même chose, au même moment.\n\nAvez-vous des questions ? Uniquement historiques, je vous prie.",
    "f_salle_artistes_sportifs": "Voici la Salle des sportifs de Sovarka, camarades. Ici sont célébrés ceux qui ont porté haut nos couleurs, à Novomirsk, à Krasnov et à Starovka.\n\nIgor Sedov, footballeur de Novomirsk. Le plus grand buteur de l'histoire du championnat national. Il était inarrêtable, surtout en troisième mi-temps. Il était célèbre pour fêter chaque but en buvant une bouteille de vodka cul sec. Il n'a jamais marqué plus de 3 buts par match, ceci expliquant cela...\n\nArvydas Tkatchenko, basketteur de Krasnov, était un véritable colosse. Repéré à 12 ans par l'entraîneur de la ville alors qu'il combattait les ours à mains nues dans la forêt de Krasnov, où il était bûcheron, il eut des débuts de basketteur compliqués… pour les panneaux de basket, qui ont dû être spécialement renforcés à cause de ses dunks destructeurs. Il est le symbole de la puissance sovarkienne.\n\nAndreï Volkov, perchiste de Novomirsk, était surnommé l'Oiseau. Avec sa perche, il déviait les lois de la pesanteur. La légende dit qu'il a eu un orteil gelé à la suite d'un saut qui l'a propulsé dans la stratosphère. Un accident avec un satellite a mis prématurément fin à sa carrière. Andreï est la seule personne au monde pour qui « Sky is not the limit ».\n\nBatyr Nourbaïev, biathlète de Starovka, était prédestiné à devenir un champion. Fils de fermier, il accompagnait les troupeaux de rennes à ski et devait les défendre contre les attaques de loups et d'ours polaires. Ses capacités hors normes lui ont valu d'être recruté par l'armée de Sovarka, où il fut nommé capitaine de la compagnie chargée de défendre la frontière nord du pays. Mais qui pouvait bien arriver par le nord, quand on est la ville la plus au nord du monde… ?\n\nEnfin, Elena Gromova, gymnaste de Krasnov, dix fois championne nationale. Non, camarades, aucun lien avec le président Gromov. La ressemblance des noms est un pur hasard, comme toutes les ressemblances de ce musée. Elle incarne à elle seule la force et la grâce de notre belle nation.\n\nLe sport, camarades, enseigne l'effort, la discipline et le respect des résultats officiels.\n\nAvez-vous des questions ? Uniquement historiques, je vous prie.",
    "f_salle_civils_intellectuels": "Voici la Salle des artistes de Sovarka, camarades. La création y est libre, totalement libre, dans le cadre prévu à cet effet.\n\nAlexeï Mironov, poète. Son recueil « Odes au Plan quinquennal » fut tiré à deux millions d'exemplaires, un pour chaque foyer, et sa lecture fut rendue obligatoire. Jamais un poète n'a été autant lu. Son second recueil, plus personnel, n'a jamais été retrouvé. Lui non plus, d'ailleurs, pendant quelques années.\n\nLe groupe Severny Veter, « Vent du Nord », le premier groupe de rock de Sovarka. Leur premier album fut interdit. Le deuxième aussi. Le troisième, « Hymne au Tracteur », est enfin passé à la radio d'État. Les fans de la première heure n'en parlent jamais.\n\nViktor Roudenko, sculpteur du bois et de la glace, à la tronçonneuse. Ses statues de glace des héros de la nation sont d'une fidélité saisissante, jusqu'au printemps. Il fallait chaque année tout recommencer. L'État y vit la plus belle métaphore de la révolution permanente.\n\nSergueï Kravtsov, peintre. Il a consacré sa vie aux paysages de Sovarka : usines, cheminées, fumées. Les critiques étrangers lui reprochaient de peindre toujours le même tableau. C'est faux : il a peint aussi la fumée par temps de neige.\n\nL'art, camarades, élève l'âme du peuple. Tant qu'il ne l'élève pas trop haut.\n\nAvez-vous des questions ? Uniquement historiques, je vous prie.",
    "f_salle_grandes_villes": "Voici la Salle des grandes crises de Sovarka, camarades. Un peuple fort ne cache pas ses épreuves : il les expose, sous verre, avec un éclairage soigné.\n\nLa famine des années vingt. Les historiens étrangers parlent de famine. Chez nous, on parle de « période de sobriété alimentaire volontaire ». Dans la vitrine, la carte de rationnement, le sac de farine et le dernier pain de l'époque. Il est authentique. Personne n'a osé le manger.\n\nLa Grande Guerre. Nos soldats ont combattu avec un courage que le monde entier nous envie. Je vous rappelle que Sovarka n'a jamais été conquise. Les villes en ruines que vous voyez sur ce tableau ont été réorganisées de manière stratégique par notre état-major.\n\nLa grève générale des années trente. Les ouvriers réclamaient des droits pour les travailleurs. Le Parti leur a donné entière satisfaction : la grève a été déclarée illégale, puisque les travailleurs étaient désormais au pouvoir. Contre qui auraient-ils fait grève ? Contre eux-mêmes ?\n\nEt enfin, la plus douloureuse de toutes : la finale de 1937, perdue contre El Estado. Ce jour-là, la nation entière a pleuré. Aujourd'hui encore, notre cœur saigne : jamais Sovarka ne se remettra de cette défaite. On n'oublie pas, on apprend simplement à vivre avec cette blessure indélébile. Notre arbitre avait pourtant été soigneusement choisi. Le leur aussi, hélas. La revanche n'a jamais eu lieu : El Estado refuse toujours de rejouer ce match. Il faut croire qu'ils ont peur.\n\nAvez-vous des questions ? Uniquement historiques, je vous prie. Et si possible, pas sur le football.",
    "f_expositions_temporaires": "Voici la Salle des expositions tournantes, camarades. Admirez. Vous ne voyez rien ? C'est normal : l'exposition précédente est terminée, et la suivante n'a pas encore été réservée. Certains visiteurs y voient une œuvre d'art à part entière : « Vitrines vides », le seul chef-d'œuvre de Sovarka que l'État n'a jamais eu à censurer. Si vous souhaitez exposer, adressez-vous à l'accueil."
  },
  "en": {
    "q_title": "Questions for the guide",
    "q_intro": "For 1 AP, Ouliana answers three questions in this room (once a day).",
    "q_open": "Ask questions (1 AP)",
    "q_placeholder": "Your historical question…",
    "q_ask": "Ask ({n} left)",
    "q_you": "You",
    "q_wait": "Ouliana is thinking…",
    "q_done": "Ouliana politely invites you to continue the tour.",
    "q_error": "Ouliana cannot answer right now. No question was counted.",
    "q_r_pas_sur_place": "You must be in one of the museum’s rooms.",
    "q_r_questions_epuisees": "You have already asked your three questions in this room today.",
    "q_r_dialogue_non_ouvert": "First open the questions (1 AP).",
    "q_r_pa_insuffisants": "You do not have enough AP.",
    "q_r_autre": "The server did not confirm. Nothing was charged.",
    "tGuide": "Ouliana Historiskaïa, official guide",
    "listen": "Listen to the guide",
    "f_hall": "Hello and welcome to the Museum of the Republic of Sovarka, comrades. I am Ouliana Historiskaïa, the museum's official guide, at the service of history. Official history, of course: it is the only one that has been preserved.\n\nThe tour will take you from the great presidents to the great parties, from our military heroes to our artists, not forgetting tractorism, our athletes and our great crises. I advise you to follow the order of the visit. Nothing is forbidden, of course. It is simply recommended, very strongly.\n\nPhotography is allowed everywhere, except where it is not. The guards will let you know.\n\nDo you have any questions? Historical ones only, please.",
    "f_salle_presidents": "Welcome to the Hall of Presidents, comrade visitors. Come closer, come closer.\n\nHere are the five great guides who led Sovarka down the path of progress.\n\nOn the left, Comrade Arkadi Ivanovich Zolotov, the first President of our Republic. He inaugurated the Presidential Palace. For thirty years he honoured with his presence every opening of a factory, bridge and school in the country. No president has ever cut so many ribbons in the service of the people.\n\nNext comes Taras Sergeyevich Belov. We owe him the famous decree on teatime, still in force today. A text of rare stability: never contested, never repealed.\n\nComrade Boris Nikolayevich Gromov was re-elected seven times. The people loved him so much that he did not even need to stand as a candidate.\n\nHe was succeeded by Vladimir Petrovich Lebedev. You will no doubt notice the resemblance to his predecessor… It is indeed striking. The people, who had loved Comrade Gromov so dearly, naturally transferred a great deal of their affection to him. Lebedev was also a great champion of dialogue between institutions: his correspondence with the People's Council is kept in the archives… in triplicate.\n\nFinally, Gennadi Andreyevich Sokolov. Yes, the same jaw, the same gaze. Voters saw it as a sign of admirable continuity. He gave the Palace its silver samovar, which still warms the highest deliberations of the State today.\n\nThere is, of course, no family tie between these three great men. Their surnames prove it. The civil registers of the time were unfortunately destroyed in the archive fire, but official historiography is categorical.\n\nAnd those two empty frames, you ask? They await the future leaders whom the people will have the wisdom to choose. Who knows… perhaps one of you?\n\nDo you have any questions? Let me remind you that I only answer historical questions.",
    "f_salle_politiques": "This is the Hall of Victorious Political Parties. Admire these banners: each bears the face of an elected president, and behind each face, the great party that carried him to power.\n\nFor yes, a President is merely the humble representative of the party that carried him to power, and the party itself is merely the modest structure that represents the sovereign people.\n\nLet us begin with the Party of Political Precursors. They led our nation out of the tsarist darkness towards the highly democratic life we know today. Highly democratic, yes. I choose my words carefully. The Party gave Sovarka its first two presidents, Comrade Zolotov and Comrade Belov. In the display case you will see the first Party card, the pen that signed the Constitution, and a photograph of the first free election. You can clearly make out the ballot box, and the Party representative who ensured its protection.\n\nIn the centre, the Party of the Happy Proletariat, Comrade Gromov's party. Its programme fitted in one sentence: the proletariat is happy. Studies of the time confirmed it one hundred percent. The Party then dissolved itself, its mission accomplished.\n\nFinally, the Party of Nostalgic Progress, which gave the country Comrades Lebedev and Sokolov. Its motto: “Advance towards the past without ever moving back.” Some countries call this the \"moonwalk\", others the Estadian tango. Its opponents, traitors to the nation who had to be re-educated, said it had nothing new to offer. That was precisely its whole programme.\n\nYou may notice that Comrades Lebedev and Sokolov look very much like Comrade Gromov, although they belonged to another party. It proves that here, pluralism does not prevent continuity.\n\nThese three great parties have one thing in common: they won every election they stood in. The other parties? They were not ready. Perhaps they are today… The registration books are at the town hall.\n\nDo you have any questions? Historical ones only, please.",
    "f_salle_honneur_militaire_nationale": "Come closer, comrades. You are entering the Hall of Military Honours. Here, every medal tells of a victory, and every victory has been duly certified by the Ministry of Defence of the Motherland.\n\nIn the large display case, the dress uniform of the first commander of the People's Army. It bears forty-seven medals: nearly fifteen kilos of metal. Historians agree that he earned every one of them, including those he awarded himself. During the Krasnov assassination attempt, they saved his life: the bullet, fired straight at his heart, flattened against them, leaving only a slight bruise.\n\nOn this wall, the map of the Great Defence of the North. Our soldiers held their positions there for eleven winters, against an enemy who, for lack of documents, remains unknown to this day. He never came: proof that the defence was perfect. Note, moreover, that Sovarka has never been conquered. It is one of its greatest sources of pride.\n\nThis dented helmet belonged to Private Piotr Neviyev, hero of the nation. He was the first to cross the frozen river during the march of 1924. The second was his commander, who wanted to make sure the ice was solid.\n\nFinally, notice the roll of honour of conscripts. Every citizen called up proudly signs his name in it. Those who did not sign appear in another register, kept elsewhere.\n\nDo you have any questions? Historical ones only, please.",
    "f_salle_organisations": "Welcome to the Hall of Tractorism, comrades. You are at the very heart of Sovarka's soul.\n\nTractorism is not a superstition: it is a scientific religion. It teaches that the Collective Tractor ploughs the fields as it ploughs consciences, in a straight line and without ever moving back. And in a well-ploughed conscience, the seeds of freedom and emancipation always end up sprouting.\n\nIn this display case, the Holy Spark Plug, found intact in the first tractor of the Krasnov kolkhoz. Many miracles are attributed to it. The best known is that of the winter of 1931: the tractor started first time.\n\nOn this wall, the Ten Commandments of Maintenance. The first: “Thou shalt change the oil every five thousand kilometres.” The tenth: “Thou shalt not covet thy neighbour's tractor, for all tractors belong to the people.”\n\nNotice these liturgical garments: the blue dungarees for high feasts and the work overalls for ordinary days. Comrade Pontiff Tractorenko still wears them for the Blessing of the Engines, every spring, at the Great Church.\n\nThe State and tractorism are perfectly separate, of course. They simply happen to think the same thing, at the same moment.\n\nDo you have any questions? Historical ones only, please.",
    "f_salle_artistes_sportifs": "This is the Hall of Sovarka's Athletes, comrades. Here we celebrate those who flew our colours high, in Novomirsk, Krasnov and Starovka.\n\nIgor Sedov, footballer from Novomirsk. The greatest goalscorer in the history of the national championship. He was unstoppable, especially in the third half. He was famous for celebrating each goal by downing a bottle of vodka in one go. He never scored more than 3 goals per match, which explains a lot...\n\nArvydas Tkatchenko, basketball player from Krasnov, was a true colossus. Spotted at the age of 12 by the town coach while he was wrestling bears bare-handed in the Krasnov forest, where he worked as a lumberjack, his beginnings as a basketball player were difficult… for the backboards, which had to be specially reinforced because of his destructive dunks. He is the symbol of Sovarkan might.\n\nAndreï Volkov, pole vaulter from Novomirsk, was nicknamed the Bird. With his pole, he bent the laws of gravity. Legend has it that he got a frozen toe after a jump that propelled him into the stratosphere. An accident with a satellite cut his career short. Andreï is the only person in the world for whom “Sky is not the limit”.\n\nBatyr Nourbaïev, biathlete from Starovka, was destined to become a champion. A farmer's son, he followed the reindeer herds on skis and had to defend them against wolves and polar bears. His extraordinary abilities got him recruited by the Sovarka army, where he was appointed captain of the company in charge of defending the country's northern border. But who could possibly come from the north, when you are the northernmost town in the world… ?\n\nFinally, Elena Gromova, gymnast from Krasnov, ten-time national champion. No, comrades, no relation to President Gromov. The similarity of names is pure coincidence, like all the resemblances in this museum. She alone embodies the strength and grace of our beautiful nation.\n\nSport, comrades, teaches effort, discipline and respect for official results.\n\nDo you have any questions? Historical ones only, please.",
    "f_salle_civils_intellectuels": "This is the Hall of Sovarka's Artists, comrades. Creation here is free, completely free, within the framework provided for that purpose.\n\nAlexeï Mironov, poet. His collection “Odes to the Five-Year Plan” was printed in two million copies, one for every household, and reading it was made compulsory. Never has a poet been so widely read. His second collection, more personal, was never found. Nor was he, for that matter, for a few years.\n\nThe band Severny Veter, “North Wind”, Sovarka's first rock band. Their first album was banned. So was the second. The third, “Hymn to the Tractor”, finally made it onto State radio. The early fans never talk about it.\n\nViktor Roudenko, sculptor of wood and ice, with a chainsaw. His ice statues of the nation's heroes are strikingly lifelike, until spring. Everything had to be started again every year. The State saw in it the finest metaphor for permanent revolution.\n\nSergueï Kravtsov, painter. He devoted his life to the landscapes of Sovarka: factories, chimneys, smoke. Foreign critics accused him of always painting the same picture. That is untrue: he also painted smoke in snowy weather.\n\nArt, comrades, elevates the soul of the people. As long as it does not elevate it too high.\n\nDo you have any questions? Historical ones only, please.",
    "f_salle_grandes_villes": "This is the Hall of Sovarka's Great Crises, comrades. A strong people does not hide its ordeals: it displays them, under glass, with careful lighting.\n\nThe famine of the twenties. Foreign historians speak of famine. Here, we speak of a “period of voluntary dietary sobriety”. In the display case: the ration card, the sack of flour and the last loaf of the era. It is authentic. Nobody dared to eat it.\n\nThe Great War. Our soldiers fought with a courage the whole world envies. Let me remind you that Sovarka has never been conquered. The ruined towns you see in this painting were strategically reorganised by our general staff.\n\nThe general strike of the thirties. The workers demanded rights for workers. The Party gave them full satisfaction: the strike was declared illegal, since the workers were now in power. Against whom would they have gone on strike? Against themselves?\n\nAnd finally, the most painful of all: the 1937 final, lost to El Estado. That day, the whole nation wept. Even today, our heart still bleeds: Sovarka will never recover from this defeat. We do not forget; we simply learn to live with this indelible wound. Our referee had been carefully chosen, though. Theirs too, alas. The rematch never took place: El Estado still refuses to replay the match. They must be afraid.\n\nDo you have any questions? Historical ones only, please. And if possible, not about football.",
    "f_expositions_temporaires": "This is the Hall of Rotating Exhibitions, comrades. Admire. You see nothing? That is normal: the previous exhibition has ended, and the next one has not yet been booked. Some visitors see it as a work of art in its own right: “Empty Display Cases”, the only masterpiece in Sovarka that the State has never had to censor. If you wish to exhibit, please enquire at the reception."
  },
  "es": {
    "q_title": "Preguntas a la guía",
    "q_intro": "Por 1 PA, Ouliana responde a tres preguntas en esta sala (una vez al día).",
    "q_open": "Hacer preguntas (1 PA)",
    "q_placeholder": "Su pregunta histórica…",
    "q_ask": "Preguntar (quedan {n})",
    "q_you": "Usted",
    "q_wait": "Ouliana reflexiona…",
    "q_done": "Ouliana le invita amablemente a continuar la visita.",
    "q_error": "Ouliana no puede responder por el momento. No se ha contado ninguna pregunta.",
    "q_r_pas_sur_place": "Debe encontrarse en una sala del museo.",
    "q_r_questions_epuisees": "Ya ha hecho sus tres preguntas en esta sala hoy.",
    "q_r_dialogue_non_ouvert": "Abra primero las preguntas (1 PA).",
    "q_r_pa_insuffisants": "No tiene suficientes PA.",
    "q_r_autre": "El servidor no lo confirmó. No se ha cobrado nada.",
    "tGuide": "Ouliana Historiskaïa, guía oficial",
    "listen": "Escuchar a la guía",
    "f_hall": "Buenos días y bienvenidos al Museo de la República de Sovarka, camaradas. Soy Ouliana Historiskaïa, guía oficial del museo, al servicio de la historia. De la historia oficial, se entiende: es la única que se ha conservado.\n\nEl recorrido les llevará de los grandes presidentes a los grandes partidos, de nuestros héroes militares a nuestros artistas, sin olvidar el tractorismo, nuestros deportistas y nuestras grandes crisis. Les aconsejo seguir el orden de la visita. Nada está prohibido, por supuesto. Simplemente se aconseja, muy encarecidamente.\n\nLa fotografía está permitida en todas partes, salvo donde no lo está. Los vigilantes se lo indicarán.\n\n¿Tienen preguntas? Solo históricas, por favor.",
    "f_salle_presidents": "Bienvenidos a la Sala de los presidentes, camaradas visitantes. Acérquense, acérquense.\n\nHe aquí los cinco grandes guías que condujeron a Sovarka por el camino del progreso.\n\nA la izquierda, el camarada Arkadi Ivánovich Zolotov, primer Presidente de nuestra República. Fue él quien inauguró el Palacio presidencial. Durante treinta años honró con su presencia cada inauguración de fábrica, de puente y de escuela del país. Ningún presidente ha cortado tantas cintas al servicio del pueblo.\n\nViene después Taras Serguéievich Belov. Le debemos el célebre decreto sobre la hora del té, todavía vigente hoy. Un texto de una estabilidad excepcional: nunca impugnado, nunca derogado.\n\nEl camarada Borís Nikoláievich Gromov fue reelegido siete veces. El pueblo lo quería tanto que ni siquiera necesitó presentarse como candidato.\n\nLe sucedió Vladímir Petróvich Lébedev. Sin duda notan el parecido con su predecesor… Es, en efecto, inquietante. El pueblo, que tanto había querido al camarada Gromov, trasladó naturalmente sobre él gran parte de su afecto. Lébedev fue también un gran defensor del diálogo entre las instituciones: su correspondencia con el Consejo del Pueblo se conserva en los archivos… por triplicado.\n\nPor último, Guennadi Andréievich Sokolov. Sí, la misma mandíbula, la misma mirada. Los electores vieron en ello la señal de una admirable continuidad. Regaló al Palacio su samovar de plata, que aún hoy calienta las más altas deliberaciones del Estado.\n\nNo existe, por supuesto, ningún parentesco entre estos tres grandes hombres. Los apellidos lo demuestran. Los registros civiles de la época quedaron lamentablemente destruidos en el incendio de los archivos, pero la historiografía oficial es tajante.\n\n¿Y esos dos marcos vacíos, me dirán? Esperan a los futuros dirigentes que el pueblo tendrá la sabiduría de elegir. Quién sabe… ¿quizá uno de ustedes?\n\n¿Tienen preguntas? Les recuerdo que solo respondo a preguntas históricas.",
    "f_salle_politiques": "He aquí la Sala de los partidos políticos victoriosos. Admiren estas banderas: cada una lleva el rostro de un presidente electo y, detrás de cada rostro, el gran partido que lo llevó al poder.\n\nPorque sí, un Presidente no es más que el humilde representante del partido que lo llevó al poder, y el partido no es a su vez más que la modesta estructura que representa al pueblo soberano.\n\nEmpecemos por el Partido de los Precursores Políticos. Fueron ellos quienes sacaron a nuestra nación de las tinieblas zaristas hacia la vida altamente democrática que conocemos hoy. Altamente democrática, sí. Peso mis palabras. El Partido dio a Sovarka sus dos primeros presidentes, el camarada Zolotov y el camarada Belov. En la vitrina verán el primer carné del Partido, la pluma que firmó la Constitución y una fotografía del primer escrutinio libre. Se distingue muy bien la urna, y al representante del Partido que garantizaba su protección.\n\nEn el centro, el Partido del Proletariado Feliz, el del camarada Gromov. Su programa cabía en una frase: el proletariado es feliz. Los estudios de la época lo confirmaron al cien por cien. Después, el Partido se disolvió por sí mismo, cumplida su misión.\n\nPor último, el Partido del Progreso Nostálgico, que dio al país a los camaradas Lébedev y Sokolov. Su lema: «Avanzar hacia el pasado sin retroceder jamás». Algunos países lo llaman el \"moonwalk\"; otros, el tango estadiense. Sus adversarios, traidores a la nación a los que hubo que reeducar, decían que no tenía nada nuevo que proponer. Ese era precisamente todo su programa.\n\nQuizá noten que los camaradas Lébedev y Sokolov se parecen mucho al camarada Gromov, aunque pertenecían a otro partido. Es la prueba de que, entre nosotros, el pluralismo no impide la continuidad.\n\nEstos tres grandes partidos tienen algo en común: ganaron todas las elecciones a las que se presentaron. ¿Los demás partidos? No estaban preparados. Quizá lo estén hoy… Los registros de inscripción están en el ayuntamiento.\n\n¿Tienen preguntas? Solo históricas, por favor.",
    "f_salle_honneur_militaire_nationale": "Acérquense, camaradas. Entran en la Sala de los honores militares. Aquí, cada medalla cuenta una victoria, y cada victoria ha sido debidamente homologada por el Ministerio de Defensa de la Patria.\n\nEn la gran vitrina, el uniforme de gala del primer comandante del Ejército Popular. Lleva cuarenta y siete medallas: casi quince kilos de metal. Los historiadores coinciden en que las mereció todas, incluidas las que se impuso a sí mismo. Durante el atentado de Krasnov le salvaron la vida: la bala, disparada en pleno corazón, se aplastó contra ellas y solo le causó un leve hematoma.\n\nEn esta pared, el mapa de la Gran Defensa del Norte. Nuestros soldados mantuvieron allí sus posiciones durante once inviernos, frente a un enemigo que, a falta de documentos, sigue siendo desconocido. Nunca llegó: prueba de que la defensa fue perfecta. Fíjense, por cierto, en que Sovarka nunca ha sido conquistada. Es uno de sus mayores orgullos.\n\nEste casco abollado perteneció al soldado Piotr Neviyev, héroe de la nación. Fue el primero en cruzar el río helado durante la marcha de 1924. El segundo fue su comandante, que quería asegurarse de que el hielo era sólido.\n\nObserven, por último, el registro de honor de los reclutas. Cada ciudadano llamado a filas inscribe en él su nombre con orgullo. Los que no se inscribieron figuran en otro registro, conservado en otro lugar.\n\n¿Tienen preguntas? Solo históricas, por favor.",
    "f_salle_organisations": "Bienvenidos a la Sala del tractorismo, camaradas. Están en el corazón del alma de Sovarka.\n\nEl tractorismo no es una superstición: es una religión científica. Enseña que el Tractor Colectivo ara los campos como ara las conciencias, en línea recta y sin retroceder jamás. Y en una conciencia bien arada, las semillas de la libertad y la emancipación siempre acaban germinando.\n\nEn esta vitrina, la Santa Bujía, una bujía de encendido hallada intacta en el primer tractor del koljós de Krasnov. Se le atribuyen numerosos milagros. El más conocido es el del invierno de 1931: el tractor arrancó a la primera.\n\nEn esta pared, los Diez Mandamientos del Mantenimiento. El primero: «Cambiarás el aceite cada cinco mil kilómetros». El décimo: «No codiciarás el tractor de tu prójimo, pues todos los tractores pertenecen al pueblo».\n\nObserven estas vestiduras litúrgicas: el peto azul de las grandes fiestas y el mono de trabajo de los días corrientes. El Camarada Pontífice Tractorenko aún los lleva en la Bendición de los Motores, cada primavera, en la Gran Iglesia.\n\nEl Estado y el tractorismo están perfectamente separados, por supuesto. Simplemente ocurre que piensan lo mismo, en el mismo momento.\n\n¿Tienen preguntas? Solo históricas, por favor.",
    "f_salle_artistes_sportifs": "He aquí la Sala de los deportistas de Sovarka, camaradas. Aquí se celebra a quienes llevaron bien alto nuestros colores, en Novomirsk, Krasnov y Starovka.\n\nIgor Sedov, futbolista de Novomirsk. El mayor goleador de la historia del campeonato nacional. Era imparable, sobre todo en el tercer tiempo. Era famoso por celebrar cada gol bebiéndose una botella de vodka de un trago. Nunca marcó más de 3 goles por partido, lo que lo explica todo...\n\nArvydas Tkatchenko, jugador de baloncesto de Krasnov, era un auténtico coloso. Descubierto a los 12 años por el entrenador de la ciudad mientras luchaba con osos a mano limpia en el bosque de Krasnov, donde era leñador, sus comienzos en el baloncesto fueron complicados… para los tableros, que tuvieron que reforzarse especialmente por culpa de sus mates destructores. Es el símbolo del poderío sovarkiano.\n\nAndréi Volkov, saltador con pértiga de Novomirsk, era apodado el Pájaro. Con su pértiga desafiaba las leyes de la gravedad. La leyenda cuenta que se le congeló un dedo del pie tras un salto que lo propulsó a la estratosfera. Un accidente con un satélite puso fin prematuramente a su carrera. Andréi es la única persona del mundo para quien «Sky is not the limit».\n\nBatyr Nourbaïev, biatleta de Starovka, estaba predestinado a ser campeón. Hijo de granjero, acompañaba a los rebaños de renos en esquís y debía defenderlos de los lobos y de los osos polares. Sus capacidades excepcionales le valieron ser reclutado por el ejército de Sovarka, donde fue nombrado capitán de la compañía encargada de defender la frontera norte del país. Pero ¿quién podría llegar por el norte, cuando se es la ciudad más septentrional del mundo… ?\n\nPor último, Elena Gromova, gimnasta de Krasnov, diez veces campeona nacional. No, camaradas, ningún parentesco con el presidente Gromov. La similitud de los apellidos es pura casualidad, como todos los parecidos de este museo. Ella sola encarna la fuerza y la gracia de nuestra hermosa nación.\n\nEl deporte, camaradas, enseña el esfuerzo, la disciplina y el respeto de los resultados oficiales.\n\n¿Tienen preguntas? Solo históricas, por favor.",
    "f_salle_civils_intellectuels": "He aquí la Sala de los artistas de Sovarka, camaradas. La creación es aquí libre, totalmente libre, dentro del marco previsto para ello.\n\nAlexéi Mironov, poeta. Su poemario «Odas al Plan quinquenal» tuvo una tirada de dos millones de ejemplares, uno por hogar, y su lectura fue obligatoria. Nunca un poeta fue tan leído. Su segundo poemario, más personal, nunca se encontró. Él tampoco, por cierto, durante algunos años.\n\nEl grupo Severny Veter, «Viento del Norte», el primer grupo de rock de Sovarka. Su primer álbum fue prohibido. El segundo también. El tercero, «Himno al Tractor», por fin sonó en la radio del Estado. Los fans de la primera hora nunca hablan de él.\n\nVíktor Rudenko, escultor de madera y hielo, con motosierra. Sus estatuas de hielo de los héroes de la nación son de una fidelidad asombrosa, hasta la primavera. Había que volver a empezarlo todo cada año. El Estado vio en ello la más bella metáfora de la revolución permanente.\n\nSerguéi Kravtsov, pintor. Consagró su vida a los paisajes de Sovarka: fábricas, chimeneas, humo. Los críticos extranjeros le reprochaban pintar siempre el mismo cuadro. Es falso: también pintó el humo con nieve.\n\nEl arte, camaradas, eleva el alma del pueblo. Mientras no la eleve demasiado.\n\n¿Tienen preguntas? Solo históricas, por favor.",
    "f_salle_grandes_villes": "He aquí la Sala de las grandes crisis de Sovarka, camaradas. Un pueblo fuerte no oculta sus pruebas: las expone, bajo vidrio, con una iluminación cuidada.\n\nLa hambruna de los años veinte. Los historiadores extranjeros hablan de hambruna. Aquí hablamos de «periodo de sobriedad alimentaria voluntaria». En la vitrina, la cartilla de racionamiento, el saco de harina y el último pan de la época. Es auténtico. Nadie se atrevió a comérselo.\n\nLa Gran Guerra. Nuestros soldados combatieron con un valor que el mundo entero nos envidia. Les recuerdo que Sovarka nunca ha sido conquistada. Las ciudades en ruinas que ven en este cuadro fueron reorganizadas de forma estratégica por nuestro estado mayor.\n\nLa huelga general de los años treinta. Los obreros reclamaban derechos para los trabajadores. El Partido les dio plena satisfacción: la huelga fue declarada ilegal, puesto que los trabajadores estaban ya en el poder. ¿Contra quién habrían hecho huelga? ¿Contra sí mismos?\n\nY por último, la más dolorosa de todas: la final de 1937, perdida contra El Estado. Ese día, la nación entera lloró. Aún hoy nuestro corazón sangra: Sovarka jamás se recuperará de esta derrota. No olvidamos; simplemente aprendemos a vivir con esta herida imborrable. Y eso que nuestro árbitro había sido cuidadosamente elegido. El suyo también, por desgracia. La revancha nunca tuvo lugar: El Estado sigue negándose a volver a jugar ese partido. Debe de ser que tienen miedo.\n\n¿Tienen preguntas? Solo históricas, por favor. Y, si es posible, no sobre fútbol.",
    "f_expositions_temporaires": "He aquí la Sala de las exposiciones rotativas, camaradas. Admiren. ¿No ven nada? Es normal: la exposición anterior ha terminado y la siguiente todavía no ha sido reservada. Algunos visitantes ven en ella una obra de arte por derecho propio: «Vitrinas vacías», la única obra maestra de Sovarka que el Estado nunca ha tenido que censurar. Si desean exponer, diríjanse a la recepción."
  },
  "zh-TW": {
    "q_title": "向導覽員提問",
    "q_intro": "花費 1 PA，Ouliana 會在此展廳回答三個問題（每天一次）。",
    "q_open": "提問（1 PA）",
    "q_placeholder": "您的歷史問題……",
    "q_ask": "提問（剩餘 {n} 個）",
    "q_you": "您",
    "q_wait": "Ouliana 正在思考……",
    "q_done": "Ouliana 有禮貌地請您繼續參觀。",
    "q_error": "Ouliana 目前無法回答。不會扣除任何問題。",
    "q_r_pas_sur_place": "您必須身在博物館的展廳內。",
    "q_r_questions_epuisees": "您今天已在此展廳問完三個問題。",
    "q_r_dialogue_non_ouvert": "請先開啟提問（1 PA）。",
    "q_r_pa_insuffisants": "您的 PA 不足。",
    "q_r_autre": "伺服器未確認。未扣除任何費用。",
    "tGuide": "Ouliana Historiskaïa，官方導覽員",
    "listen": "聆聽導覽員",
    "f_hall": "同志們好，歡迎來到索瓦卡共和國博物館。我是 Ouliana Historiskaïa，本館的官方導覽員，為歷史服務。當然，是為官方歷史服務：這是唯一被保存下來的歷史。\n\n參觀路線將帶您從偉大的總統走到偉大的政黨，從我們的軍事英雄走到我們的藝術家，也不會漏掉拖拉機教、我們的運動員和我們的重大危機。我建議您依照參觀順序前進。當然，什麼都沒有禁止。只是建議，而且是非常強烈的建議。\n\n館內處處都可以拍照，除了不可以拍照的地方。警衛會提醒您。\n\n有問題嗎？請只問歷史問題。",
    "f_salle_presidents": "歡迎來到總統廳，各位同志訪客。請靠近，請靠近。\n\n這五位偉大的領路人，帶領索瓦卡走上進步之路。\n\n左邊是阿爾卡季·伊凡諾維奇·佐洛托夫同志，我們共和國的首任總統。總統府就是由他揭幕。三十年來，他親臨全國每一座工廠、每一座橋樑、每一所學校的落成典禮。沒有任何一位總統為人民剪過這麼多的綵帶。\n\n接著是塔拉斯·謝爾蓋耶維奇·別洛夫。我們要感謝他頒布了著名的下午茶時間法令，至今仍然有效。這是一份罕見穩定的文件：從未受到質疑，從未被廢除。\n\n鮑里斯·尼古拉耶維奇·格羅莫夫同志連任七次。人民愛他愛到他甚至不需要登記參選。\n\n接任他的是弗拉基米爾·彼得羅維奇·列別傑夫。您一定注意到他和前任的相似之處……確實令人驚訝。曾經如此深愛格羅莫夫同志的人民，自然而然把大部分的愛轉移到他身上。列別傑夫也是機構間對話的偉大捍衛者：他與人民委員會的往來信件保存在檔案館裡……一式三份。\n\n最後是根納季·安德烈耶維奇·索科洛夫。是的，同樣的下顎，同樣的眼神。選民們從中看見了令人讚嘆的延續。他把銀製茶炊獻給總統府，至今仍溫暖著國家最高層級的議事。\n\n當然，這三位偉人之間沒有任何親屬關係。他們的姓氏就是證明。可惜當年的戶籍登記在檔案館大火中燒毀了，但官方史學的結論是明確的。\n\n那兩個空畫框呢，您問？它們在等待人民以智慧選出的未來領導人。誰知道呢……也許就是您們其中一位？\n\n有問題嗎？提醒您，我只回答歷史問題。",
    "f_salle_politiques": "這裡是勝選政黨廳。請欣賞這些旗幟：每一面都印著一位當選總統的面孔，而每張面孔背後，都是將他推上權位的偉大政黨。\n\n沒錯，總統不過是將他推上權位的政黨的謙卑代表，而政黨本身也不過是代表主權人民的樸素組織。\n\n讓我們從政治先驅黨開始。正是他們帶領我們的國家走出沙皇的黑暗，邁向今日我們所熟知的高度民主生活。高度民主，是的。我字斟句酌。這個黨為索瓦卡產生了前兩任總統：佐洛托夫同志與別洛夫同志。在展示櫃裡，您會看到第一張黨證、簽署憲法的那支筆，以及第一次自由選舉的照片。照片上可以清楚看到投票箱，以及負責保護它的黨代表。\n\n中間是幸福無產階級黨，也就是格羅莫夫同志的政黨。它的綱領只有一句話：無產階級是幸福的。當年的研究百分之百證實了這一點。之後，這個黨完成使命，自行解散。\n\n最後是懷舊進步黨，為國家產生了列別傑夫同志與索科洛夫同志。它的口號是：「向過去前進，絕不後退。」有些國家稱之為「月球漫步」，也有些國家稱之為埃斯塔多探戈。它的對手——那些必須接受再教育的國家叛徒——說它提不出任何新東西。這正是它全部的綱領。\n\n您也許會注意到，列別傑夫同志和索科洛夫同志長得很像格羅莫夫同志，儘管他們屬於另一個政黨。這證明在我們這裡，多元主義並不妨礙延續。\n\n這三大政黨有一個共同點：他們贏得了所參加的每一場選舉。其他政黨呢？他們還沒準備好。也許今天準備好了……登記簿就在市政廳。\n\n有問題嗎？請只問歷史問題。",
    "f_salle_honneur_militaire_nationale": "請靠近，同志們。您正進入軍事榮譽廳。在這裡，每一枚勳章都訴說一場勝利，而每一場勝利都經過祖國國防部正式認證。\n\n大展示櫃裡是人民軍首任司令的禮服。上面有四十七枚勳章：將近十五公斤的金屬。史學家一致認為每一枚都是他應得的，包括他頒給自己的那些。在克拉斯諾夫刺殺事件中，這些勳章救了他一命：正中心臟的子彈撞扁在勳章上，只讓他留下輕微的瘀青。\n\n這面牆上是北方大防衛的地圖。我們的士兵在那裡堅守陣地十一個冬天，對抗一個因缺乏文件而至今身分不明的敵人。敵人從未出現：這證明防衛是完美的。順帶一提，索瓦卡從未被征服過。這是它最大的驕傲之一。\n\n這頂凹陷的頭盔屬於國家英雄彼得·涅維耶夫二等兵。他在 1924 年的行軍中第一個渡過結冰的河。第二個是他的指揮官，因為指揮官堅持要確認冰面夠結實。\n\n最後，請注意徵召兵榮譽名冊。每一位應召入伍的公民都自豪地在上面簽下名字。沒有簽名的人，則記錄在另一本名冊裡，存放在別的地方。\n\n有問題嗎？請只問歷史問題。",
    "f_salle_organisations": "歡迎來到拖拉機教廳，同志們。您正站在索瓦卡靈魂的核心。\n\n拖拉機教不是迷信，而是一門科學的宗教。它教導我們：集體拖拉機耕耘田地，正如它耕耘人心，筆直前進，絕不後退。而在一顆被好好耕耘過的心裡，自由與解放的種子終究會發芽。\n\n這個展示櫃裡是聖火星塞，在克拉斯諾夫集體農場的第一台拖拉機裡完好無缺地被找到。人們認為它創造了許多奇蹟。最著名的是 1931 年冬天的奇蹟：拖拉機一次就發動了。\n\n這面牆上是保養十誡。第一誡：「每五千公里你當更換機油。」第十誡：「不可貪戀鄰人的拖拉機，因為所有拖拉機都屬於人民。」\n\n請看這些禮儀服裝：盛大節日穿的藍色吊帶工作褲，以及平日穿的工作服。拖拉機科同志教宗至今仍會在每年春天大教堂的引擎祝福禮上穿著它們。\n\n當然，國家與拖拉機教是完全分離的。只是它們碰巧會在同一時刻想著同一件事。\n\n有問題嗎？請只問歷史問題。",
    "f_salle_artistes_sportifs": "這裡是索瓦卡運動員廳，同志們。這裡表彰那些在新米爾斯克、克拉斯諾夫和斯塔羅夫卡高舉我們旗幟的人。\n\n伊戈爾·謝多夫，新米爾斯克的足球員。全國聯賽史上最偉大的射手。他勢不可擋，尤其是在第三個半場。他以每進一球就一口氣乾掉一瓶伏特加來慶祝而聞名。他每場從未進過超過 3 球，這也就說明了一切……\n\n阿爾維達斯·特卡琴科，克拉斯諾夫的籃球員，是個真正的巨人。12 歲時，他在擔任伐木工的克拉斯諾夫森林裡徒手與熊搏鬥，被市隊教練發掘。他的籃球生涯起步艱難……對籃板來說，因為他毀滅性的灌籃，籃板必須特別加固。他是索瓦卡力量的象徵。\n\n安德烈·沃爾科夫，新米爾斯克的撐竿跳選手，綽號「飛鳥」。他靠著撐竿扭轉了重力定律。傳說他有一次跳躍把自己彈進平流層，因而凍傷了一根腳趾。一場與人造衛星的事故讓他提早結束了運動生涯。安德烈是世上唯一一個「Sky is not the limit」的人。\n\n巴特爾·努爾巴耶夫，斯塔羅夫卡的冬季兩項選手，注定成為冠軍。身為農夫之子，他滑雪跟著馴鹿群，還得保護牠們免受狼和北極熊的攻擊。他非凡的能力讓他被索瓦卡軍隊招募，並被任命為負責守衛國家北方邊界的連長。可是，當你是世界最北的城市時，到底有誰會從北方來呢……？\n\n最後是葉蓮娜·格羅莫娃，克拉斯諾夫的體操選手，十度全國冠軍。不，同志們，她和格羅莫夫總統毫無關係。姓氏相似純屬巧合，就像這座博物館裡所有的相似之處一樣。她一人便體現了我們美麗國家的力量與優雅。\n\n同志們，運動教會我們努力、紀律，以及尊重官方結果。\n\n有問題嗎？請只問歷史問題。",
    "f_salle_civils_intellectuels": "這裡是索瓦卡藝術家廳，同志們。這裡的創作是自由的，完全自由——在為此劃定的範圍之內。\n\n阿列克謝·米羅諾夫，詩人。他的詩集《五年計畫頌》印了兩百萬冊，每戶一本，而且規定必須閱讀。從來沒有一位詩人被這麼多人讀過。他的第二本詩集更為私人，從未被找到。順帶一提，他本人也有好幾年沒被找到。\n\n「北風」樂團，索瓦卡第一個搖滾樂團。他們的第一張專輯被禁。第二張也是。第三張《拖拉機頌歌》終於在國家電台播出。最早的樂迷從來不提這張。\n\n維克多·魯堅科，用鏈鋸創作的木雕與冰雕家。他的國家英雄冰雕逼真得驚人——直到春天。每年都得從頭再來。國家從中看見了不斷革命最美的隱喻。\n\n謝爾蓋·克拉夫佐夫，畫家。他一生致力於描繪索瓦卡的風景：工廠、煙囪、濃煙。外國評論家批評他總是畫同一幅畫。這不是真的：他也畫過下雪天的濃煙。\n\n同志們，藝術提升人民的靈魂。只要別提升得太高。\n\n有問題嗎？請只問歷史問題。",
    "f_salle_grandes_villes": "這裡是索瓦卡重大危機廳，同志們。堅強的民族不會隱藏自己的苦難：而是把它們放在玻璃櫃裡展示，配上精心的燈光。\n\n二〇年代的饑荒。外國史學家稱之為饑荒。我們這裡稱之為「自願飲食節制時期」。展示櫃裡有配給卡、一袋麵粉，以及那個年代的最後一塊麵包。它是真品。沒有人敢吃它。\n\n大戰。我們的士兵以全世界都羨慕的勇氣作戰。提醒您，索瓦卡從未被征服過。您在這幅畫中看到的廢墟城市，是由我們的參謀本部進行了策略性的重整。\n\n三〇年代的大罷工。工人們要求勞動者的權利。黨完全滿足了他們：罷工被宣布為非法，因為勞動者此時已經掌權。他們還要對誰罷工呢？對他們自己嗎？\n\n最後，是最令人痛心的一場：1937 年決賽，敗給了埃斯塔多。那一天，全國都哭了。直到今天，我們的心仍在淌血：索瓦卡永遠無法從這場失敗中恢復。我們不會忘記，我們只是學著與這道無法抹滅的傷口共存。我們的裁判明明是精心挑選的。可惜，他們的也是。復仇戰從未舉行：埃斯塔多至今仍拒絕重賽。看來他們是害怕了。\n\n有問題嗎？請只問歷史問題。而且可以的話，別問足球。",
    "f_expositions_temporaires": "這裡是輪展廳，同志們。請欣賞。什麼都沒看到？這很正常：上一檔展覽已經結束，下一檔還沒有人預訂。有些訪客認為這本身就是一件藝術品：《空展示櫃》，索瓦卡唯一一件國家從未需要審查的傑作。如果您想展出，請洽詢櫃檯。"
  },
  "ru": {
    "q_title": "Вопросы гиду",
    "q_intro": "За 1 ОД Ульяна ответит на три вопроса в этом зале (раз в день).",
    "q_open": "Задать вопросы (1 ОД)",
    "q_placeholder": "Ваш исторический вопрос…",
    "q_ask": "Спросить (осталось: {n})",
    "q_you": "Вы",
    "q_wait": "Ульяна размышляет…",
    "q_done": "Ульяна вежливо приглашает вас продолжить осмотр.",
    "q_error": "Ульяна сейчас не может ответить. Вопрос не засчитан.",
    "q_r_pas_sur_place": "Нужно находиться в одном из залов музея.",
    "q_r_questions_epuisees": "Вы уже задали сегодня три вопроса в этом зале.",
    "q_r_dialogue_non_ouvert": "Сначала откройте вопросы (1 ОД).",
    "q_r_pa_insuffisants": "У вас недостаточно ОД.",
    "q_r_autre": "Сервер не подтвердил. Ничего не списано.",
    "tGuide": "Ульяна Историская, официальный гид",
    "listen": "Послушать гида",
    "f_hall": "Здравствуйте и добро пожаловать в Музей Республики Соварка, товарищи. Я Ульяна Историская, официальный гид музея, на службе у истории. Официальной истории, разумеется: только она и сохранилась.\n\nМаршрут проведёт вас от великих президентов к великим партиям, от наших военных героев к нашим деятелям искусства, не забывая о тракторизме, наших спортсменах и наших великих кризисах. Советую следовать порядку осмотра. Ничего не запрещено, конечно. Просто рекомендуется — очень настоятельно.\n\nФотографировать можно везде, кроме тех мест, где нельзя. Смотрители вам подскажут.\n\nЕсть вопросы? Только исторические, прошу вас.",
    "f_salle_presidents": "Добро пожаловать в Зал президентов, товарищи посетители. Подходите, подходите.\n\nПеред вами пять великих вождей, которые повели Соварку по пути прогресса.\n\nСлева — товарищ Аркадий Иванович Золотов, первый Президент нашей Республики. Именно он открыл Президентский дворец. Тридцать лет он почтил своим присутствием открытие каждого завода, моста и школы в стране. Ни один президент не перерезал столько ленточек на службе народу.\n\nДалее — Тарас Сергеевич Белов. Ему мы обязаны знаменитым указом о времени чаепития, который действует до сих пор. Текст редкой устойчивости: ни разу не оспорен, ни разу не отменён.\n\nТоварищ Борис Николаевич Громов переизбирался семь раз. Народ любил его так сильно, что ему даже не требовалось выдвигать свою кандидатуру.\n\nЕго сменил Владимир Петрович Лебедев. Вы, несомненно, замечаете сходство с его предшественником… Оно и правда поразительное. Народ, так любивший товарища Громова, естественным образом перенёс на него немалую часть своей любви. Лебедев был также большим сторонником диалога между институтами: его переписка с Советом народа хранится в архиве… в трёх экземплярах.\n\nИ наконец, Геннадий Андреевич Соколов. Да, та же челюсть, тот же взгляд. Избиратели увидели в этом знак замечательной преемственности. Он подарил Дворцу свой серебряный самовар, который и сегодня согревает высшие совещания государства.\n\nНикакого родства между этими тремя великими людьми, разумеется, нет. Фамилии это доказывают. Записи актов гражданского состояния того времени, к сожалению, сгорели при пожаре в архиве, но официальная историография однозначна.\n\nА эти две пустые рамы, спросите вы? Они ждут будущих руководителей, которых народ в своей мудрости изберёт. Кто знает… может быть, одного из вас?\n\nЕсть вопросы? Напоминаю, что я отвечаю только на исторические вопросы.",
    "f_salle_politiques": "Перед вами Зал победивших политических партий. Полюбуйтесь этими знамёнами: на каждом — лицо избранного президента, а за каждым лицом — великая партия, приведшая его к власти.\n\nВедь да, Президент — всего лишь скромный представитель партии, приведшей его к власти, а партия — всего лишь скромная структура, представляющая суверенный народ.\n\nНачнём с Партии политических предтеч. Именно она вывела нашу нацию из царской тьмы к той высокодемократической жизни, которую мы знаем сегодня. Высокодемократической, да. Я взвешиваю свои слова. Партия дала Соварке двух первых президентов — товарища Золотова и товарища Белова. В витрине вы увидите первый партийный билет, перо, которым подписали Конституцию, и фотографию первых свободных выборов. На ней хорошо видны урна и представитель Партии, обеспечивавший её охрану.\n\nВ центре — Партия счастливого пролетариата, партия товарища Громова. Её программа умещалась в одну фразу: пролетариат счастлив. Исследования того времени подтвердили это на сто процентов. Затем Партия самораспустилась, выполнив свою миссию.\n\nИ наконец, Партия ностальгического прогресса, давшая стране товарищей Лебедева и Соколова. Её девиз: «Идти вперёд в прошлое, никогда не отступая». В некоторых странах это называют «лунной походкой», в других — эстадским танго. Её противники, предатели нации, которых пришлось перевоспитать, говорили, что ей нечего предложить нового. В этом-то и состояла вся её программа.\n\nВозможно, вы заметите, что товарищи Лебедев и Соколов очень похожи на товарища Громова, хотя и принадлежали к другой партии. Это доказывает, что у нас плюрализм не мешает преемственности.\n\nУ этих трёх великих партий есть общая черта: они выиграли все выборы, в которых участвовали. Другие партии? Они были не готовы. Возможно, сегодня готовы… Списки для регистрации находятся в мэрии.\n\nЕсть вопросы? Только исторические, прошу вас.",
    "f_salle_honneur_militaire_nationale": "Подходите, товарищи. Вы входите в Зал воинской славы. Здесь каждая медаль рассказывает о победе, и каждая победа должным образом утверждена Министерством обороны Родины.\n\nВ большой витрине — парадный мундир первого командующего Народной армией. На нём сорок семь медалей: почти пятнадцать килограммов металла. Историки сходятся во мнении, что он заслужил их все, включая те, которыми наградил себя сам. Во время покушения в Краснове они спасли ему жизнь: пуля, выпущенная прямо в сердце, расплющилась о них, оставив лишь лёгкий синяк.\n\nНа этой стене — карта Великой обороны Севера. Наши солдаты удерживали там позиции одиннадцать зим против врага, который за отсутствием документов до сих пор неизвестен. Он так и не пришёл: доказательство того, что оборона была безупречной. Заметьте, кстати, что Соварка никогда не была завоёвана. Это одна из её величайших гордостей.\n\nЭта помятая каска принадлежала рядовому Петру Невиеву, герою нации. Он первым перешёл замёрзшую реку во время похода 1924 года. Вторым был его командир, желавший убедиться, что лёд крепкий.\n\nОбратите внимание, наконец, на почётный список призывников. Каждый гражданин, призванный под знамёна, с гордостью вписывает туда своё имя. Те, кто не вписался, значатся в другом списке, который хранится в другом месте.\n\nЕсть вопросы? Только исторические, прошу вас.",
    "f_salle_organisations": "Добро пожаловать в Зал тракторизма, товарищи. Вы в самом сердце души Соварки.\n\nТракторизм — не суеверие, а научная религия. Он учит, что Коллективный Трактор пашет поля так же, как пашет сознание: по прямой и никогда не отступая. И в хорошо вспаханном сознании семена свободы и освобождения всегда в конце концов прорастают.\n\nВ этой витрине — Святая Свеча, свеча зажигания, найденная целой в первом тракторе красновского колхоза. Ей приписывают множество чудес. Самое известное — чудо зимы 1931 года: трактор завёлся с первого раза.\n\nНа этой стене — Десять заповедей техобслуживания. Первая: «Меняй масло каждые пять тысяч километров». Десятая: «Не желай трактора ближнего твоего, ибо все тракторы принадлежат народу».\n\nОбратите внимание на эти литургические облачения: синий комбинезон для больших праздников и рабочая спецовка для будних дней. Товарищ понтифик Тракторенко по-прежнему надевает их на Освящение моторов каждую весну в Большой церкви.\n\nГосударство и тракторизм, разумеется, полностью разделены. Просто случается, что они думают одно и то же в один и тот же момент.\n\nЕсть вопросы? Только исторические, прошу вас.",
    "f_salle_artistes_sportifs": "Перед вами Зал спортивной славы Соварки, товарищи. Здесь чествуют тех, кто высоко нёс наши цвета — в Новомирске, Краснове и Старовке.\n\nИгорь Седов, футболист из Новомирска. Лучший бомбардир в истории национального чемпионата. Его невозможно было остановить, особенно в третьем тайме. Он славился тем, что отмечал каждый гол, выпивая бутылку водки залпом. Он никогда не забивал больше 3 голов за матч, что многое объясняет...\n\nАрвидас Ткаченко, баскетболист из Краснова, был настоящим колоссом. Его в 12 лет заметил городской тренер, когда он голыми руками боролся с медведями в красновском лесу, где работал лесорубом. Начало его баскетбольной карьеры было непростым… для щитов, которые пришлось специально укреплять из-за его разрушительных данков. Он — символ соварской мощи.\n\nАндрей Волков, прыгун с шестом из Новомирска, носил прозвище Птица. С помощью шеста он обходил законы тяготения. Легенда гласит, что он отморозил палец на ноге после прыжка, забросившего его в стратосферу. Столкновение со спутником преждевременно оборвало его карьеру. Андрей — единственный человек в мире, для которого «Sky is not the limit».\n\nБатыр Нурбаев, биатлонист из Старовки, был рождён стать чемпионом. Сын фермера, он сопровождал оленьи стада на лыжах и защищал их от волков и белых медведей. Его исключительные способности привели его в армию Соварки, где он стал капитаном роты, охраняющей северную границу страны. Но кто, скажите на милость, мог прийти с севера, если это самый северный город в мире… ?\n\nИ наконец, Елена Громова, гимнастка из Краснова, десятикратная чемпионка страны. Нет, товарищи, никакого родства с президентом Громовым. Сходство фамилий — чистая случайность, как и все сходства в этом музее. Она одна воплощает силу и грацию нашей прекрасной нации.\n\nСпорт, товарищи, учит усилию, дисциплине и уважению к официальным результатам.\n\nЕсть вопросы? Только исторические, прошу вас.",
    "f_salle_civils_intellectuels": "Перед вами Зал деятелей искусств Соварки, товарищи. Творчество здесь свободно, совершенно свободно — в отведённых для этого рамках.\n\nАлексей Миронов, поэт. Его сборник «Оды пятилетнему плану» вышел тиражом два миллиона экземпляров, по одному на каждую семью, и его чтение было обязательным. Ни одного поэта так много не читали. Его второй, более личный сборник так и не нашли. Как, впрочем, и его самого — несколько лет.\n\nГруппа «Северный ветер», первая рок-группа Соварки. Их первый альбом запретили. Второй тоже. Третий, «Гимн трактору», наконец-то прозвучал на государственном радио. Фанаты первой волны о нём никогда не говорят.\n\nВиктор Руденко, скульптор по дереву и льду, работающий бензопилой. Его ледяные статуи героев нации поразительно похожи — до весны. Каждый год приходилось начинать всё заново. Государство увидело в этом прекраснейшую метафору перманентной революции.\n\nСергей Кравцов, живописец. Он посвятил жизнь пейзажам Соварки: заводы, трубы, дым. Иностранные критики упрекали его в том, что он всегда пишет одну и ту же картину. Это неправда: он писал ещё и дым в снегопад.\n\nИскусство, товарищи, возвышает душу народа. Лишь бы не слишком высоко.\n\nЕсть вопросы? Только исторические, прошу вас.",
    "f_salle_grandes_villes": "Перед вами Зал великих кризисов Соварки, товарищи. Сильный народ не скрывает своих испытаний: он выставляет их под стеклом, с аккуратной подсветкой.\n\nГолод двадцатых годов. Иностранные историки говорят о голоде. У нас говорят о «периоде добровольной пищевой умеренности». В витрине — продовольственная карточка, мешок муки и последний хлеб той эпохи. Он подлинный. Никто не осмелился его съесть.\n\nВеликая война. Наши солдаты сражались с мужеством, которому завидует весь мир. Напоминаю, что Соварка никогда не была завоёвана. Города в руинах, которые вы видите на этой картине, были стратегически реорганизованы нашим генштабом.\n\nВсеобщая забастовка тридцатых годов. Рабочие требовали прав для трудящихся. Партия полностью их удовлетворила: забастовку объявили незаконной, ведь трудящиеся теперь сами были у власти. Против кого им было бастовать? Против самих себя?\n\nИ наконец, самый болезненный из всех: финал 1937 года, проигранный Эль Эстадо. В тот день плакала вся нация. Наше сердце кровоточит до сих пор: Соварка никогда не оправится от этого поражения. Мы не забываем — мы просто учимся жить с этой неизгладимой раной. А ведь наш судья был тщательно выбран. Их судья, увы, тоже. Реванш так и не состоялся: Эль Эстадо до сих пор отказывается переиграть этот матч. Видимо, боятся.\n\nЕсть вопросы? Только исторические, прошу вас. И по возможности не о футболе.",
    "f_expositions_temporaires": "Перед вами Зал сменных выставок, товарищи. Любуйтесь. Ничего не видите? Это нормально: предыдущая выставка закончилась, а следующую ещё не забронировали. Некоторые посетители видят в этом самостоятельное произведение искусства: «Пустые витрины» — единственный шедевр Соварки, который государству ни разу не пришлось цензурировать. Если хотите выставиться, обратитесь в приёмную."
  },
  "ko": {
    "q_title": "해설사에게 질문",
    "q_intro": "1 PA로 울리아나가 이 방에서 질문 세 개에 답합니다(하루 한 번).",
    "q_open": "질문하기 (1 PA)",
    "q_placeholder": "역사에 관한 질문…",
    "q_ask": "질문하기 ({n}개 남음)",
    "q_you": "당신",
    "q_wait": "울리아나가 생각 중입니다…",
    "q_done": "울리아나가 정중하게 관람을 계속하시라고 권합니다.",
    "q_error": "울리아나가 지금은 답할 수 없습니다. 질문은 차감되지 않았습니다.",
    "q_r_pas_sur_place": "박물관 전시실 안에 있어야 합니다.",
    "q_r_questions_epuisees": "오늘 이 방에서 질문 세 개를 이미 했습니다.",
    "q_r_dialogue_non_ouvert": "먼저 질문을 여세요 (1 PA).",
    "q_r_pa_insuffisants": "PA가 부족합니다.",
    "q_r_autre": "서버가 확인하지 않았습니다. 아무것도 차감되지 않았습니다.",
    "tGuide": "울리아나 이스토리스카야, 공식 해설사",
    "listen": "해설사의 설명 듣기",
    "f_hall": "안녕하십니까, 소바르카 공화국 박물관에 오신 것을 환영합니다, 동지 여러분. 저는 역사에 봉사하는 박물관 공식 해설사 울리아나 이스토리스카야입니다. 물론 공식 역사에 봉사하지요. 보존된 역사는 그것뿐이니까요.\n\n관람 동선은 위대한 대통령들에서 위대한 정당들로, 우리의 군사 영웅들에서 예술가들로 이어지며, 트랙터교와 운동선수들, 그리고 우리의 큰 위기들도 빠뜨리지 않습니다. 관람 순서를 따르시길 권합니다. 물론 금지된 것은 아무것도 없습니다. 그저 권고일 뿐이지요. 아주 강력한 권고요.\n\n사진 촬영은 어디서나 허용됩니다. 허용되지 않는 곳만 빼고요. 경비원이 알려 드릴 겁니다.\n\n질문 있으십니까? 역사에 관한 질문만 부탁드립니다.",
    "f_salle_presidents": "대통령의 방에 오신 것을 환영합니다, 동지 관람객 여러분. 가까이 오세요, 가까이.\n\n소바르카를 진보의 길로 이끈 다섯 분의 위대한 지도자입니다.\n\n왼쪽은 우리 공화국의 초대 대통령 아르카디 이바노비치 졸로토프 동지입니다. 대통령궁을 개관한 분이 바로 이분이지요. 삼십 년 동안 전국의 모든 공장, 다리, 학교 개관식에 몸소 참석하셨습니다. 인민을 위해 이분만큼 많은 테이프를 자른 대통령은 없습니다.\n\n다음은 타라스 세르게예비치 벨로프입니다. 지금도 유효한 그 유명한 차 마시는 시간에 관한 법령이 이분 덕분입니다. 보기 드물게 안정적인 문서지요. 한 번도 이의 제기된 적도, 폐지된 적도 없습니다.\n\n보리스 니콜라예비치 그로모프 동지는 일곱 번 재선되었습니다. 인민이 그를 너무나 사랑해서 후보로 나설 필요조차 없었지요.\n\n그 뒤를 이은 분은 블라디미르 페트로비치 레베데프입니다. 전임자와 닮은 점이 분명 눈에 띄실 겁니다… 정말 놀라울 정도지요. 그로모프 동지를 그토록 사랑했던 인민은 자연스럽게 그 애정의 상당 부분을 그에게 옮겼습니다. 레베데프는 기관 간 대화의 위대한 옹호자이기도 했습니다. 인민평의회와 주고받은 그의 서신은 기록보관소에 보관되어 있지요… 세 부씩.\n\n마지막으로 겐나디 안드레예비치 소콜로프입니다. 네, 같은 턱, 같은 눈빛입니다. 유권자들은 거기서 감탄할 만한 연속성의 징표를 보았지요. 그는 대통령궁에 은제 사모바르를 기증했고, 그것은 오늘날에도 국가의 최고 회의를 따뜻하게 데우고 있습니다.\n\n물론 이 세 위인 사이에는 어떤 혈연관계도 없습니다. 성이 그것을 증명하지요. 안타깝게도 당시의 호적 기록은 기록보관소 화재로 소실되었지만, 공식 역사학의 입장은 단호합니다.\n\n그럼 저 빈 액자 두 개는요? 인민이 지혜롭게 선택할 미래의 지도자들을 기다리고 있습니다. 누가 알겠습니까… 어쩌면 여러분 중 한 분일지도요?\n\n질문 있으십니까? 다시 말씀드리지만 저는 역사에 관한 질문에만 답합니다.",
    "f_salle_politiques": "승리한 정당들의 방입니다. 이 깃발들을 감상해 보십시오. 깃발마다 당선된 대통령의 얼굴이 있고, 그 얼굴 뒤에는 그를 권좌에 올린 위대한 정당이 있습니다.\n\n그렇습니다. 대통령은 그를 권좌에 올린 정당의 겸손한 대표일 뿐이고, 정당 또한 주권자인 인민을 대표하는 소박한 조직일 뿐이지요.\n\n먼저 정치선구자당부터 보시죠. 이들이 우리 민족을 차르 시대의 어둠에서 오늘날 우리가 아는 고도로 민주적인 삶으로 이끌었습니다. 고도로 민주적이지요. 네, 말을 신중히 고르고 있습니다. 이 당은 소바르카에 첫 두 대통령, 졸로토프 동지와 벨로프 동지를 배출했습니다. 진열장에는 첫 당원증, 헌법에 서명한 펜, 그리고 첫 자유선거 사진이 있습니다. 투표함과, 그 투표함을 지키던 당 대표가 아주 잘 보이지요.\n\n가운데는 그로모프 동지의 정당, 행복한 프롤레타리아당입니다. 강령은 한 문장이었습니다. 프롤레타리아는 행복하다. 당시의 연구가 이를 백 퍼센트 확인했지요. 그 뒤 당은 사명을 다하고 스스로 해산했습니다.\n\n마지막으로 레베데프 동지와 소콜로프 동지를 배출한 향수진보당입니다. 표어는 “결코 물러서지 않고 과거를 향해 전진하라”입니다. 어떤 나라들은 이것을 “문워크”라 부르고, 또 어떤 나라들은 에스타도 탱고라 부르지요. 재교육이 필요했던 민족의 반역자인 반대파는 이 당이 새로 내놓을 게 없다고 했습니다. 그게 바로 이 당의 강령 전부였지요.\n\n레베데프 동지와 소콜로프 동지가 다른 당 소속인데도 그로모프 동지와 아주 닮았다는 걸 눈치채셨을지도 모르겠습니다. 우리나라에서는 다원주의가 연속성을 막지 않는다는 증거지요.\n\n이 세 위대한 정당에는 공통점이 하나 있습니다. 출마한 모든 선거에서 승리했다는 것이지요. 다른 정당들요? 준비가 안 되어 있었습니다. 오늘은 준비가 되었을지도 모르지요… 등록 명부는 시청에 있습니다.\n\n질문 있으십니까? 역사에 관한 질문만 부탁드립니다.",
    "f_salle_honneur_militaire_nationale": "가까이 오십시오, 동지 여러분. 군사 명예의 방에 들어오셨습니다. 이곳에서는 모든 훈장이 승리를 이야기하고, 모든 승리는 조국 국방부가 정식으로 공인했습니다.\n\n큰 진열장에는 인민군 초대 사령관의 예복이 있습니다. 훈장이 마흔일곱 개, 금속만 거의 15킬로그램입니다. 역사학자들은 그가 모든 훈장을 받을 자격이 있었다는 데 동의합니다. 스스로에게 수여한 것들까지 포함해서요. 크라스노프 암살 시도 때 이 훈장들이 그의 목숨을 구했습니다. 심장을 정통으로 겨눈 총알이 훈장에 부딪혀 납작해졌고, 가벼운 멍만 남겼지요.\n\n이 벽에는 북방 대방어전의 지도가 있습니다. 우리 병사들은 그곳에서 열한 번의 겨울 동안 진지를 지켰습니다. 문서가 없어 오늘날까지도 정체를 알 수 없는 적에 맞서서요. 적은 끝내 오지 않았습니다. 방어가 완벽했다는 증거지요. 덧붙이자면 소바르카는 한 번도 정복된 적이 없습니다. 그것이 소바르카의 가장 큰 자랑 가운데 하나입니다.\n\n이 찌그러진 철모는 민족의 영웅 표트르 네비예프 이병의 것입니다. 그는 1924년 행군 때 얼어붙은 강을 맨 먼저 건넜습니다. 두 번째는 그의 지휘관이었지요. 얼음이 단단한지 꼭 확인하고 싶어 했거든요.\n\n마지막으로 징집병 명예 명부를 보십시오. 소집된 시민은 모두 자랑스럽게 여기에 이름을 적습니다. 이름을 적지 않은 사람들은 다른 명부에 올라 있고, 그 명부는 다른 곳에 보관되어 있습니다.\n\n질문 있으십니까? 역사에 관한 질문만 부탁드립니다.",
    "f_salle_organisations": "트랙터교의 방에 오신 것을 환영합니다, 동지 여러분. 여러분은 지금 소바르카 영혼의 한가운데에 계십니다.\n\n트랙터교는 미신이 아니라 과학적인 종교입니다. 집단 트랙터는 밭을 갈듯 양심을 갈며, 곧게 나아가고 결코 물러서지 않는다고 가르치지요. 그리고 잘 갈린 양심에서는 자유와 해방의 씨앗이 결국 언제나 싹을 틔웁니다.\n\n이 진열장에는 크라스노프 콜호스의 첫 트랙터에서 온전한 상태로 발견된 점화 플러그, 성 플러그가 있습니다. 수많은 기적이 이것 덕분이라고 하지요. 가장 유명한 것은 1931년 겨울의 기적입니다. 트랙터가 한 번에 시동이 걸렸거든요.\n\n이 벽에는 정비의 십계명이 있습니다. 제1계명: “너는 오천 킬로미터마다 엔진오일을 갈지어다.” 제10계명: “네 이웃의 트랙터를 탐내지 말라. 모든 트랙터는 인민의 것이니라.”\n\n이 전례복을 보십시오. 큰 축일에 입는 파란 멜빵바지와 평일에 입는 작업복입니다. 트락토렌코 교황 동지는 지금도 매년 봄 대성당에서 열리는 엔진 축복식 때 이 옷을 입습니다.\n\n물론 국가와 트랙터교는 완전히 분리되어 있습니다. 그저 같은 순간에 같은 생각을 하는 일이 있을 뿐이지요.\n\n질문 있으십니까? 역사에 관한 질문만 부탁드립니다.",
    "f_salle_artistes_sportifs": "소바르카 스포츠 영광의 방입니다, 동지 여러분. 이곳에서는 노보미르스크, 크라스노프, 스타로프카에서 우리의 깃발을 드높인 이들을 기립니다.\n\n이고르 세도프, 노보미르스크의 축구 선수입니다. 전국 리그 역사상 최고의 득점왕이지요. 그는 막을 수 없는 선수였습니다. 특히 경기 후 술자리, 이른바 ‘3쿼터’에서요. 골을 넣을 때마다 보드카 한 병을 원샷하는 세리머니로 유명했습니다. 경기당 3골 넘게 넣은 적이 없는데, 이유는 짐작하실 겁니다...\n\n아르비다스 트카첸코, 크라스노프의 농구 선수는 진정한 거인이었습니다. 12살 때 벌목꾼으로 일하던 크라스노프 숲에서 맨손으로 곰과 싸우다 시 감독의 눈에 띄었지요. 그의 농구 선수 생활은 시작부터 험난했습니다… 백보드에게 말이지요. 파괴적인 덩크 때문에 백보드를 특별히 보강해야 했거든요. 그는 소바르카 힘의 상징입니다.\n\n안드레이 볼코프, 노보미르스크의 장대높이뛰기 선수로, 별명은 ‘새’였습니다. 그는 장대로 중력의 법칙을 비틀었지요. 전설에 따르면 한 번은 성층권까지 날아오르는 바람에 발가락 하나가 동상에 걸렸다고 합니다. 인공위성과의 사고로 선수 생활을 일찍 마감했지요. 안드레이는 세상에서 유일하게 “Sky is not the limit”인 사람입니다.\n\n바티르 누르바예프, 스타로프카의 바이애슬론 선수는 챔피언이 될 운명이었습니다. 농부의 아들로 스키를 타고 순록 떼를 따라다니며 늑대와 북극곰의 공격으로부터 지켜야 했지요. 남다른 능력 덕분에 소바르카 군에 발탁되어 나라의 북쪽 국경을 지키는 중대의 중대장이 되었습니다. 그런데 세상에서 가장 북쪽에 있는 도시라면, 대체 누가 북쪽에서 올 수 있을까요… ?\n\n마지막으로 크라스노프의 체조 선수이자 전국 대회 10회 우승자인 옐레나 그로모바입니다. 아닙니다, 동지 여러분, 그로모프 대통령과는 아무 관계가 없습니다. 이름이 비슷한 것은 순전히 우연입니다. 이 박물관의 모든 닮은 점이 그렇듯이요. 그녀 혼자서 우리 아름다운 나라의 힘과 우아함을 보여 줍니다.\n\n동지 여러분, 스포츠는 노력과 규율, 그리고 공식 결과에 대한 존중을 가르칩니다.\n\n질문 있으십니까? 역사에 관한 질문만 부탁드립니다.",
    "f_salle_civils_intellectuels": "소바르카 예술가의 방입니다, 동지 여러분. 이곳에서 창작은 자유롭습니다. 그것을 위해 마련된 틀 안에서라면 완전히 자유롭지요.\n\n알렉세이 미로노프, 시인입니다. 그의 시집 『5개년 계획 송가』는 가구마다 한 권씩 이백만 부가 인쇄되었고, 읽는 것이 의무였습니다. 그토록 많이 읽힌 시인은 없었지요. 더 개인적인 두 번째 시집은 끝내 발견되지 않았습니다. 그 자신도, 말하자면, 몇 년 동안 발견되지 않았고요.\n\n소바르카 최초의 록 밴드 ‘세베르니 베테르’, 즉 ‘북풍’입니다. 첫 앨범은 금지되었습니다. 두 번째도요. 세 번째 앨범 『트랙터 찬가』가 마침내 국영 라디오에 나왔지요. 초창기 팬들은 그 앨범 얘기를 절대 하지 않습니다.\n\n빅토르 루덴코, 전기톱을 쓰는 나무와 얼음 조각가입니다. 그가 만든 민족 영웅들의 얼음 조각상은 놀라울 만큼 실물과 똑같습니다. 봄이 오기 전까지는요. 해마다 모든 걸 다시 시작해야 했지요. 국가는 거기서 영구 혁명의 가장 아름다운 은유를 보았습니다.\n\n세르게이 크랍초프, 화가입니다. 그는 평생을 소바르카의 풍경, 그러니까 공장, 굴뚝, 연기를 그리는 데 바쳤습니다. 외국 비평가들은 그가 늘 같은 그림만 그린다고 비난했지요. 사실이 아닙니다. 눈 오는 날의 연기도 그렸으니까요.\n\n동지 여러분, 예술은 인민의 영혼을 고양합니다. 너무 높이만 고양하지 않는다면요.\n\n질문 있으십니까? 역사에 관한 질문만 부탁드립니다.",
    "f_salle_grandes_villes": "소바르카 대위기의 방입니다, 동지 여러분. 강한 민족은 시련을 숨기지 않습니다. 정성스러운 조명 아래 유리 안에 전시하지요.\n\n20년대의 기근입니다. 외국 역사학자들은 기근이라고 부릅니다. 우리는 ‘자발적 식생활 절제 기간’이라고 부르지요. 진열장에는 배급표, 밀가루 자루, 그리고 그 시절의 마지막 빵이 있습니다. 진품입니다. 아무도 감히 먹지 못했지요.\n\n대전쟁입니다. 우리 병사들은 온 세상이 부러워하는 용기로 싸웠습니다. 다시 말씀드리지만 소바르카는 한 번도 정복된 적이 없습니다. 이 그림에 보이는 폐허가 된 도시들은 우리 참모본부가 전략적으로 재편한 것입니다.\n\n30년대의 총파업입니다. 노동자들은 노동자의 권리를 요구했습니다. 당은 그들을 완전히 만족시켰지요. 이제 노동자가 권력을 잡았으니 파업은 불법이라고 선언했습니다. 누구를 상대로 파업을 했겠습니까? 자기 자신을 상대로요?\n\n그리고 마지막으로, 가장 고통스러운 위기입니다. 엘 에스타도에 패한 1937년 결승전이지요. 그날 온 나라가 울었습니다. 오늘날까지도 우리 가슴은 피를 흘립니다. 소바르카는 결코 이 패배에서 회복하지 못할 겁니다. 잊지는 않습니다. 다만 이 지워지지 않는 상처와 함께 사는 법을 배울 뿐이지요. 우리 심판도 신중하게 고른 사람이었는데 말입니다. 안타깝게도 그쪽 심판도요. 설욕전은 끝내 열리지 않았습니다. 엘 에스타도는 지금도 재경기를 거부하고 있지요. 겁이 나는 모양입니다.\n\n질문 있으십니까? 역사에 관한 질문만 부탁드립니다. 그리고 가능하면 축구 얘기는 빼고요.",
    "f_expositions_temporaires": "순회 전시실입니다, 동지 여러분. 감상해 보십시오. 아무것도 안 보이신다고요? 정상입니다. 이전 전시는 끝났고, 다음 전시는 아직 예약되지 않았으니까요. 어떤 관람객들은 이것 자체를 하나의 예술 작품으로 봅니다. 『빈 진열장』, 국가가 한 번도 검열할 필요가 없었던 소바르카 유일의 걸작이지요. 전시를 원하시면 안내 데스크에 문의하십시오."
  },
  "ar": {
    "q_title": "أسئلة للمرشدة",
    "q_intro": "مقابل 1 PA، تجيب أوليانا عن ثلاثة أسئلة في هذه القاعة (مرة في اليوم).",
    "q_open": "طرح أسئلة (1 PA)",
    "q_placeholder": "سؤالك التاريخي…",
    "q_ask": "اسأل (المتبقي: {n})",
    "q_you": "أنت",
    "q_wait": "أوليانا تفكر…",
    "q_done": "تدعوك أوليانا بلطف إلى متابعة الزيارة.",
    "q_error": "لا تستطيع أوليانا الإجابة الآن. لم يُحتسب أي سؤال.",
    "q_r_pas_sur_place": "يجب أن تكون في إحدى قاعات المتحف.",
    "q_r_questions_epuisees": "لقد طرحت أسئلتك الثلاثة في هذه القاعة اليوم.",
    "q_r_dialogue_non_ouvert": "افتح الأسئلة أولًا (1 PA).",
    "q_r_pa_insuffisants": "ليس لديك ما يكفي من PA.",
    "q_r_autre": "لم يؤكد الخادم. لم يُخصم شيء.",
    "tGuide": "أوليانا هيستوريسكايا، المرشدة الرسمية",
    "listen": "الاستماع إلى المرشدة",
    "f_hall": "مرحبًا بكم في متحف جمهورية سوفاركا، أيها الرفاق. أنا أوليانا هيستوريسكايا، المرشدة الرسمية للمتحف، في خدمة التاريخ. التاريخ الرسمي بالطبع: فهو الوحيد الذي حُفظ.\n\nسيأخذكم المسار من الرؤساء العظماء إلى الأحزاب العظيمة، ومن أبطالنا العسكريين إلى فنانينا، دون أن ننسى التراكتورية ورياضيينا وأزماتنا الكبرى. أنصحكم باتباع ترتيب الزيارة. لا شيء ممنوع، بالطبع. إنه مجرد نصيحة، نصيحة شديدة جدًا.\n\nالتصوير مسموح في كل مكان، إلا حيث لا يُسمح به. وسينبهكم الحراس إلى ذلك.\n\nهل لديكم أسئلة؟ تاريخية فقط، من فضلكم.",
    "f_salle_presidents": "مرحبًا بكم في قاعة الرؤساء، أيها الرفاق الزوار. اقتربوا، اقتربوا.\n\nهؤلاء هم القادة العظماء الخمسة الذين قادوا سوفاركا على طريق التقدم.\n\nعلى اليسار، الرفيق أركادي إيفانوفيتش زولوتوف، أول رئيس لجمهوريتنا. هو من دشّن القصر الرئاسي. طوال ثلاثين عامًا شرّف بحضوره افتتاح كل مصنع وجسر ومدرسة في البلاد. لم يقصّ أي رئيس هذا القدر من الأشرطة في خدمة الشعب.\n\nثم يأتي تاراس سيرغييفيتش بيلوف. ندين له بالمرسوم الشهير حول موعد الشاي، الساري حتى اليوم. نص نادر الثبات: لم يُطعن فيه قط، ولم يُلغَ قط.\n\nأُعيد انتخاب الرفيق بوريس نيكولايفيتش غروموف سبع مرات. أحبه الشعب إلى حد أنه لم يحتج حتى إلى الترشح.\n\nوخلفه فلاديمير بتروفيتش ليبيديف. لا شك أنكم تلاحظون الشبه بسلفه… إنه مثير للحيرة فعلًا. فالشعب الذي أحب الرفيق غروموف كثيرًا نقل إليه بطبيعة الحال جزءًا كبيرًا من محبته. وكان ليبيديف أيضًا مدافعًا كبيرًا عن الحوار بين المؤسسات: مراسلاته مع مجلس الشعب محفوظة في الأرشيف… من ثلاث نسخ.\n\nوأخيرًا، غينادي أندرييفيتش سوكولوف. نعم، الفك نفسه، النظرة نفسها. رأى الناخبون في ذلك علامة على استمرارية رائعة. أهدى القصر سماوره الفضي الذي لا يزال يدفئ أرفع مداولات الدولة حتى اليوم.\n\nلا توجد، بالطبع، أي قرابة بين هؤلاء الرجال العظماء الثلاثة. والألقاب تثبت ذلك. لقد أُتلفت سجلات الأحوال المدنية لتلك الحقبة للأسف في حريق الأرشيف، لكن التأريخ الرسمي قاطع.\n\nوهذان الإطاران الفارغان، تسألونني؟ إنهما ينتظران القادة المقبلين الذين سيحسن الشعب اختيارهم بحكمته. من يدري… ربما أحدكم؟\n\nهل لديكم أسئلة؟ أذكّركم بأنني لا أجيب إلا عن الأسئلة التاريخية.",
    "f_salle_politiques": "هذه قاعة الأحزاب السياسية المنتصرة. تأملوا هذه الرايات: تحمل كل منها وجه رئيس منتخب، وخلف كل وجه، الحزب العظيم الذي أوصله إلى السلطة.\n\nفنعم، ما الرئيس إلا الممثل المتواضع للحزب الذي أوصله إلى السلطة، وما الحزب نفسه إلا البنية المتواضعة التي تمثل الشعب صاحب السيادة.\n\nلنبدأ بحزب الرواد السياسيين. هم من قادوا أمتنا خارج ظلمات القيصرية نحو الحياة الديمقراطية للغاية التي نعرفها اليوم. ديمقراطية للغاية، نعم. إنني أزن كلماتي. منح الحزب سوفاركا رئيسيها الأولين، الرفيق زولوتوف والرفيق بيلوف. في الواجهة سترون أول بطاقة حزبية، والريشة التي وُقّع بها الدستور، وصورة لأول اقتراع حر. يظهر فيها بوضوح صندوق الاقتراع، وممثل الحزب الذي كان يتولى حمايته.\n\nفي الوسط، حزب البروليتاريا السعيدة، حزب الرفيق غروموف. كان برنامجه جملة واحدة: البروليتاريا سعيدة. وقد أكدت دراسات تلك الحقبة ذلك بنسبة مئة في المئة. ثم حلّ الحزب نفسه بنفسه، بعد أن أنجز مهمته.\n\nوأخيرًا، حزب التقدم الحنيني، الذي منح البلاد الرفيقين ليبيديف وسوكولوف. شعاره: «التقدم نحو الماضي دون التراجع أبدًا». بعض البلدان تسمي ذلك «مشية القمر»، وبعضها الآخر التانغو الإستادي. وكان خصومه، خونة الأمة الذين اضطررنا إلى إعادة تأهيلهم، يقولون إنه لا يملك جديدًا يقدمه. وكان ذلك بالضبط برنامجه كله.\n\nربما تلاحظون أن الرفيقين ليبيديف وسوكولوف يشبهان الرفيق غروموف كثيرًا، مع أنهما كانا ينتميان إلى حزب آخر. هذا دليل على أن التعددية عندنا لا تمنع الاستمرارية.\n\nتشترك هذه الأحزاب الكبرى الثلاثة في أمر واحد: فازت في كل الانتخابات التي خاضتها. والأحزاب الأخرى؟ لم تكن مستعدة. ربما هي مستعدة اليوم… سجلات التسجيل موجودة في البلدية.\n\nهل لديكم أسئلة؟ تاريخية فقط، من فضلكم.",
    "f_salle_honneur_militaire_nationale": "اقتربوا، أيها الرفاق. أنتم تدخلون قاعة الأوسمة العسكرية. هنا، كل وسام يروي نصرًا، وكل نصر صادقت عليه وزارة الدفاع عن الوطن حسب الأصول.\n\nفي الواجهة الكبيرة، بزة التشريفات لأول قائد للجيش الشعبي. تحمل سبعة وأربعين وسامًا: قرابة خمسة عشر كيلوغرامًا من المعدن. يتفق المؤرخون على أنه استحقها كلها، بما فيها تلك التي منحها لنفسه. وفي محاولة اغتيال كراسنوف أنقذت حياته: فالرصاصة التي أُطلقت في قلبه مباشرة تحطمت عليها، ولم تخلّف سوى كدمة خفيفة.\n\nعلى هذا الجدار، خريطة الدفاع الكبير عن الشمال. صمد جنودنا هناك في مواقعهم أحد عشر شتاءً، في مواجهة عدو لا يزال مجهولًا حتى اليوم لغياب الوثائق. لم يأتِ قط: وهذا دليل على أن الدفاع كان مثاليًا. ولاحظوا بالمناسبة أن سوفاركا لم تُغزَ قط. وهذا من أعظم مفاخرها.\n\nهذه الخوذة المنبعجة كانت للجندي بيوتر نيفييف، بطل الأمة. كان أول من عبر النهر المتجمد خلال مسيرة 1924. وكان الثاني قائده، الذي حرص على التأكد من أن الجليد متين.\n\nلاحظوا أخيرًا سجل الشرف للمجندين. يدوّن فيه كل مواطن استُدعي إلى الخدمة اسمه بفخر. أما الذين لم يدوّنوا أسماءهم، فهم مدرجون في سجل آخر، محفوظ في مكان آخر.\n\nهل لديكم أسئلة؟ تاريخية فقط، من فضلكم.",
    "f_salle_organisations": "مرحبًا بكم في قاعة التراكتورية، أيها الرفاق. أنتم هنا في قلب روح سوفاركا.\n\nالتراكتورية ليست خرافة: إنها دين علمي. تعلّم أن الجرار الجماعي يحرث الحقول كما يحرث الضمائر، في خط مستقيم ودون أن يتراجع أبدًا. وفي ضمير محروث جيدًا، تنتهي بذور الحرية والتحرر دائمًا إلى الإنبات.\n\nفي هذه الواجهة، الشمعة المقدسة، شمعة إشعال عُثر عليها سليمة في أول جرار في كولخوز كراسنوف. تُنسب إليها معجزات كثيرة. أشهرها معجزة شتاء 1931: اشتغل الجرار من المحاولة الأولى.\n\nعلى هذا الجدار، الوصايا العشر للصيانة. الأولى: «ستغيّر الزيت كل خمسة آلاف كيلومتر». العاشرة: «لا تشتهِ جرار جارك، فكل الجرارات ملك للشعب».\n\nلاحظوا هذه الثياب الطقسية: الأفرول الأزرق للأعياد الكبرى وبزة العمل للأيام العادية. لا يزال الرفيق الحبر تراكتورينكو يرتديها في مباركة المحركات، كل ربيع، في الكنيسة الكبرى.\n\nالدولة والتراكتورية منفصلتان تمامًا، بالطبع. يحدث فقط أنهما تفكران في الشيء نفسه، في اللحظة نفسها.\n\nهل لديكم أسئلة؟ تاريخية فقط، من فضلكم.",
    "f_salle_artistes_sportifs": "هذه قاعة رياضيي سوفاركا، أيها الرفاق. هنا نحتفي بمن رفعوا ألواننا عاليًا، في نوفوميرسك وكراسنوف وستاروفكا.\n\nإيغور سيدوف، لاعب كرة قدم من نوفوميرسك. أعظم هداف في تاريخ البطولة الوطنية. كان لا يُوقَف، خصوصًا في الشوط الثالث. اشتهر بالاحتفال بكل هدف بشرب زجاجة فودكا دفعة واحدة. لم يسجل قط أكثر من 3 أهداف في المباراة، وهذا يفسر ذاك...\n\nأرفيداس تكاتشينكو، لاعب كرة سلة من كراسنوف، كان عملاقًا حقيقيًا. اكتشفه مدرب المدينة في الثانية عشرة من عمره وهو يصارع الدببة بيديه العاريتين في غابة كراسنوف، حيث كان حطابًا. وكانت بداياته في كرة السلة صعبة… على الألواح، التي اضطروا إلى تقويتها خصيصًا بسبب تسديداته الساحقة المدمرة. إنه رمز القوة السوفاركية.\n\nأندريه فولكوف، قافز بالزانة من نوفوميرسك، كان يُلقّب بالطائر. كان يتحدى بزانته قوانين الجاذبية. تقول الأسطورة إن إصبع قدمه تجمد بعد قفزة قذفت به إلى طبقة الستراتوسفير. ووضع حادث مع قمر صناعي حدًا مبكرًا لمسيرته. أندريه هو الشخص الوحيد في العالم الذي ينطبق عليه «Sky is not the limit».\n\nباتير نورباييف، رياضي البياثلون من ستاروفكا، كان مقدرًا له أن يصبح بطلًا. ابن مزارع، كان يرافق قطعان الرنة على الزلاجات ويدافع عنها في وجه الذئاب والدببة القطبية. أهّلته قدراته الاستثنائية للتجنيد في جيش سوفاركا، حيث عُيّن نقيبًا للسرية المكلفة بالدفاع عن الحدود الشمالية للبلاد. ولكن من عساه يأتي من الشمال، وهي أقصى مدن العالم شمالًا… ؟\n\nوأخيرًا، إيلينا غروموفا، لاعبة جمباز من كراسنوف، بطلة وطنية عشر مرات. لا، أيها الرفاق، لا قرابة لها بالرئيس غروموف. تشابه الأسماء محض مصادفة، مثل كل أوجه الشبه في هذا المتحف. إنها وحدها تجسد قوة أمتنا الجميلة ورشاقتها.\n\nالرياضة، أيها الرفاق، تعلّم الجهد والانضباط واحترام النتائج الرسمية.\n\nهل لديكم أسئلة؟ تاريخية فقط، من فضلكم.",
    "f_salle_civils_intellectuels": "هذه قاعة فناني سوفاركا، أيها الرفاق. الإبداع هنا حر، حر تمامًا، في الإطار المخصص لذلك.\n\nأليكسي ميرونوف، شاعر. طُبع ديوانه «أناشيد للخطة الخمسية» في مليوني نسخة، نسخة لكل بيت، وجُعلت قراءته إلزامية. لم يُقرأ شاعر قط بهذا القدر. أما ديوانه الثاني، الأكثر ذاتية، فلم يُعثر عليه قط. ولا عليه هو، بالمناسبة، لبضع سنوات.\n\nفرقة سيفيرني فيتر، «ريح الشمال»، أول فرقة روك في سوفاركا. مُنع ألبومها الأول. والثاني أيضًا. أما الثالث، «نشيد الجرار»، فقد بُث أخيرًا على إذاعة الدولة. ومعجبو البدايات لا يتحدثون عنه أبدًا.\n\nفيكتور رودينكو، نحات الخشب والجليد، بالمنشار الآلي. تماثيله الجليدية لأبطال الأمة مذهلة في دقتها، حتى الربيع. كان لا بد من البدء من جديد كل عام. ورأت الدولة في ذلك أجمل استعارة للثورة الدائمة.\n\nسيرغي كرافتسوف، رسام. كرّس حياته لمناظر سوفاركا: مصانع، مداخن، دخان. عاب عليه النقاد الأجانب أنه يرسم اللوحة نفسها دائمًا. هذا غير صحيح: لقد رسم أيضًا الدخان في الطقس المثلج.\n\nالفن، أيها الرفاق، يسمو بروح الشعب. ما دام لا يسمو بها عاليًا أكثر من اللازم.\n\nهل لديكم أسئلة؟ تاريخية فقط، من فضلكم.",
    "f_salle_grandes_villes": "هذه قاعة الأزمات الكبرى في سوفاركا، أيها الرفاق. الشعب القوي لا يخفي محنه: بل يعرضها، تحت الزجاج، بإضاءة متقنة.\n\nمجاعة العشرينيات. يتحدث المؤرخون الأجانب عن مجاعة. أما نحن فنتحدث عن «فترة الاعتدال الغذائي الطوعي». في الواجهة، بطاقة التموين، وكيس الطحين، وآخر رغيف خبز من تلك الحقبة. إنه أصلي. لم يجرؤ أحد على أكله.\n\nالحرب الكبرى. قاتل جنودنا بشجاعة يحسدنا عليها العالم كله. أذكّركم بأن سوفاركا لم تُغزَ قط. المدن المدمرة التي ترونها في هذه اللوحة أعادت هيئة أركاننا تنظيمها بطريقة استراتيجية.\n\nالإضراب العام في الثلاثينيات. كان العمال يطالبون بحقوق للعمال. فلبّى الحزب مطالبهم كاملة: أُعلن الإضراب غير قانوني، لأن العمال صاروا هم في السلطة. ضد من كانوا سيضربون؟ ضد أنفسهم؟\n\nوأخيرًا، أشدها إيلامًا: نهائي 1937، الذي خسرناه أمام إل إستادو. في ذلك اليوم، بكت الأمة كلها. ولا يزال قلبنا ينزف حتى اليوم: لن تتعافى سوفاركا أبدًا من هذه الهزيمة. نحن لا ننسى، بل نتعلم فقط أن نعيش مع هذا الجرح الذي لا يندمل. ومع أن حكمنا كان قد اختير بعناية. وحكمهم أيضًا، للأسف. لم تُلعب مباراة الثأر قط: لا تزال إل إستادو ترفض إعادة هذه المباراة. لا بد أنهم خائفون.\n\nهل لديكم أسئلة؟ تاريخية فقط، من فضلكم. وإن أمكن، ليس عن كرة القدم.",
    "f_expositions_temporaires": "هذه قاعة المعارض المتجددة، أيها الرفاق. تأملوا. لا ترون شيئًا؟ هذا طبيعي: انتهى المعرض السابق، ولم يُحجز المعرض التالي بعد. يرى فيها بعض الزوار عملًا فنيًا قائمًا بذاته: «واجهات فارغة»، التحفة الوحيدة في سوفاركا التي لم تضطر الدولة قط إلى مراقبتها. إن رغبتم في العرض، فتوجهوا إلى الاستقبال."
  },
  "pt-BR": {
    "q_title": "Perguntas à guia",
    "q_intro": "Por 1 PA, Ouliana responde a três perguntas nesta sala (uma vez por dia).",
    "q_open": "Fazer perguntas (1 PA)",
    "q_placeholder": "Sua pergunta histórica…",
    "q_ask": "Perguntar (restam {n})",
    "q_you": "Você",
    "q_wait": "Ouliana está pensando…",
    "q_done": "Ouliana convida você educadamente a continuar a visita.",
    "q_error": "Ouliana não pode responder agora. Nenhuma pergunta foi contada.",
    "q_r_pas_sur_place": "Você precisa estar em uma sala do museu.",
    "q_r_questions_epuisees": "Você já fez suas três perguntas nesta sala hoje.",
    "q_r_dialogue_non_ouvert": "Abra primeiro as perguntas (1 PA).",
    "q_r_pa_insuffisants": "Você não tem PA suficientes.",
    "q_r_autre": "O servidor não confirmou. Nada foi cobrado.",
    "tGuide": "Ouliana Historiskaïa, guia oficial",
    "listen": "Ouvir a guia",
    "f_hall": "Bom dia e bem-vindos ao Museu da República de Sovarka, camaradas. Sou Ouliana Historiskaïa, guia oficial do museu, a serviço da história. Da história oficial, claro: é a única que foi preservada.\n\nO percurso vai levá-los dos grandes presidentes aos grandes partidos, dos nossos heróis militares aos nossos artistas, sem esquecer o tratorismo, nossos atletas e nossas grandes crises. Aconselho que sigam a ordem da visita. Nada é proibido, é claro. É apenas recomendado, muito enfaticamente.\n\nA fotografia é permitida em toda parte, exceto onde não é. Os guardas vão avisá-los.\n\nAlguma pergunta? Apenas históricas, por favor.",
    "f_salle_presidents": "Bem-vindos à Sala dos presidentes, camaradas visitantes. Aproximem-se, aproximem-se.\n\nEis os cinco grandes guias que conduziram Sovarka no caminho do progresso.\n\nÀ esquerda, o camarada Arkadi Ivanovitch Zolotov, primeiro Presidente da nossa República. Foi ele quem inaugurou o Palácio presidencial. Durante trinta anos, honrou com sua presença cada inauguração de fábrica, de ponte e de escola do país. Nenhum presidente cortou tantas fitas a serviço do povo.\n\nEm seguida vem Taras Sergueievitch Belov. Devemos a ele o célebre decreto sobre a hora do chá, ainda em vigor hoje. Um texto de rara estabilidade: nunca contestado, nunca revogado.\n\nO camarada Boris Nikolaievitch Gromov foi reeleito sete vezes. O povo o amava tanto que ele nem precisou se candidatar.\n\nSucedeu-o Vladimir Petrovitch Lebedev. Vocês certamente notam a semelhança com seu antecessor… Ela é, de fato, perturbadora. O povo, que tanto amara o camarada Gromov, transferiu naturalmente para ele grande parte de seu afeto. Lebedev foi também um grande defensor do diálogo entre as instituições: sua correspondência com o Conselho do Povo está guardada nos arquivos… em três vias.\n\nPor fim, Guennadi Andreievitch Sokolov. Sim, o mesmo queixo, o mesmo olhar. Os eleitores viram nisso o sinal de uma admirável continuidade. Ele ofereceu ao Palácio seu samovar de prata, que ainda hoje aquece as mais altas deliberações do Estado.\n\nNão existe, é claro, nenhum parentesco entre esses três grandes homens. Os sobrenomes provam isso. Os registros civis da época infelizmente foram destruídos no incêndio dos arquivos, mas a historiografia oficial é categórica.\n\nE esses dois quadros vazios, vocês me perguntam? Eles aguardam os futuros dirigentes que o povo terá a sabedoria de escolher. Quem sabe… talvez um de vocês?\n\nAlguma pergunta? Lembro que só respondo a perguntas históricas.",
    "f_salle_politiques": "Eis a Sala dos partidos políticos vitoriosos. Admirem estas bandeiras: cada uma traz o rosto de um presidente eleito e, por trás de cada rosto, o grande partido que o levou ao poder.\n\nPois sim, um Presidente não passa do humilde representante do partido que o levou ao poder, e o partido não passa, por sua vez, da modesta estrutura que representa o povo soberano.\n\nComecemos pelo Partido dos Precursores Políticos. Foram eles que conduziram nossa nação para fora das trevas czaristas, rumo à vida altamente democrática que conhecemos hoje. Altamente democrática, sim. Peso minhas palavras. O Partido deu a Sovarka seus dois primeiros presidentes, o camarada Zolotov e o camarada Belov. Na vitrine, vocês verão a primeira carteira do Partido, a pena que assinou a Constituição e uma fotografia do primeiro escrutínio livre. Distingue-se muito bem a urna, e o representante do Partido que garantia sua proteção.\n\nNo centro, o Partido do Proletariado Feliz, o do camarada Gromov. Seu programa cabia numa frase: o proletariado é feliz. Os estudos da época confirmaram isso em cem por cento. Depois, o Partido se dissolveu por conta própria, missão cumprida.\n\nPor fim, o Partido do Progresso Nostálgico, que deu ao país os camaradas Lebedev e Sokolov. Seu lema: “Avançar rumo ao passado sem jamais recuar”. Alguns países chamam isso de \"moonwalk\"; outros, de tango estadiense. Seus adversários, traidores da nação que foi preciso reeducar, diziam que ele não tinha nada de novo a propor. Esse era justamente todo o seu programa.\n\nVocês talvez notem que os camaradas Lebedev e Sokolov se parecem muito com o camarada Gromov, embora pertencessem a outro partido. É a prova de que, entre nós, o pluralismo não impede a continuidade.\n\nEsses três grandes partidos têm algo em comum: venceram todas as eleições de que participaram. Os outros partidos? Não estavam prontos. Talvez estejam hoje… Os livros de inscrição estão na prefeitura.\n\nAlguma pergunta? Apenas históricas, por favor.",
    "f_salle_honneur_militaire_nationale": "Aproximem-se, camaradas. Vocês estão entrando na Sala das honras militares. Aqui, cada medalha conta uma vitória, e cada vitória foi devidamente homologada pelo Ministério da Defesa da Pátria.\n\nNa grande vitrine, o uniforme de gala do primeiro comandante do Exército Popular. Ele tem quarenta e sete medalhas: quase quinze quilos de metal. Os historiadores concordam que ele mereceu todas, inclusive as que concedeu a si mesmo. No atentado de Krasnov, elas salvaram sua vida: a bala, disparada em pleno coração, esmagou-se contra elas, causando-lhe apenas um leve hematoma.\n\nNesta parede, o mapa da Grande Defesa do Norte. Nossos soldados mantiveram ali suas posições durante onze invernos, diante de um inimigo que, por falta de documentos, continua desconhecido até hoje. Ele nunca veio: prova de que a defesa foi perfeita. Notem, aliás, que Sovarka nunca foi conquistada. É um de seus maiores orgulhos.\n\nEste capacete amassado pertenceu ao soldado Piotr Neviyev, herói da nação. Ele foi o primeiro a atravessar o rio congelado durante a marcha de 1924. O segundo foi seu comandante, que fazia questão de verificar se o gelo era firme.\n\nObservem, por fim, o livro de honra dos convocados. Cada cidadão chamado às armas inscreve nele seu nome com orgulho. Os que não se inscreveram constam de outro livro, guardado em outro lugar.\n\nAlguma pergunta? Apenas históricas, por favor.",
    "f_salle_organisations": "Bem-vindos à Sala do tratorismo, camaradas. Vocês estão no coração da alma de Sovarka.\n\nO tratorismo não é uma superstição: é uma religião científica. Ensina que o Trator Coletivo lavra os campos como lavra as consciências, em linha reta e sem jamais recuar. E numa consciência bem lavrada, as sementes da liberdade e da emancipação sempre acabam germinando.\n\nNesta vitrine, a Santa Vela, uma vela de ignição encontrada intacta no primeiro trator do colcoz de Krasnov. Atribuem-se a ela muitos milagres. O mais conhecido é o do inverno de 1931: o trator pegou de primeira.\n\nNesta parede, os Dez Mandamentos da Manutenção. O primeiro: “Trocarás o óleo a cada cinco mil quilômetros.” O décimo: “Não cobiçarás o trator do teu próximo, pois todos os tratores pertencem ao povo.”\n\nObservem estas vestes litúrgicas: o macacão azul das grandes festas e o uniforme de trabalho dos dias comuns. O Camarada Pontífice Tractorenko ainda os usa na Bênção dos Motores, toda primavera, na Grande Igreja.\n\nO Estado e o tratorismo são perfeitamente separados, é claro. Simplesmente acontece de pensarem a mesma coisa, no mesmo momento.\n\nAlguma pergunta? Apenas históricas, por favor.",
    "f_salle_artistes_sportifs": "Eis a Sala dos atletas de Sovarka, camaradas. Aqui são celebrados aqueles que levaram bem alto as nossas cores, em Novomirsk, Krasnov e Starovka.\n\nIgor Sedov, jogador de futebol de Novomirsk. O maior artilheiro da história do campeonato nacional. Era imparável, sobretudo no terceiro tempo. Era famoso por comemorar cada gol virando uma garrafa de vodca de uma vez. Nunca marcou mais de 3 gols por partida, o que explica muita coisa...\n\nArvydas Tkatchenko, jogador de basquete de Krasnov, era um verdadeiro colosso. Descoberto aos 12 anos pelo treinador da cidade enquanto lutava com ursos de mãos nuas na floresta de Krasnov, onde era lenhador, teve um começo complicado no basquete… para as tabelas, que precisaram ser especialmente reforçadas por causa de suas enterradas destruidoras. Ele é o símbolo da potência sovarkiana.\n\nAndreï Volkov, saltador com vara de Novomirsk, tinha o apelido de Pássaro. Com sua vara, desafiava as leis da gravidade. Diz a lenda que ele congelou um dedo do pé depois de um salto que o lançou na estratosfera. Um acidente com um satélite encerrou prematuramente sua carreira. Andreï é a única pessoa no mundo para quem “Sky is not the limit”.\n\nBatyr Nourbaïev, biatleta de Starovka, estava predestinado a ser campeão. Filho de fazendeiro, acompanhava os rebanhos de renas de esqui e tinha de defendê-los dos lobos e dos ursos-polares. Suas capacidades fora do comum o levaram a ser recrutado pelo exército de Sovarka, onde foi nomeado capitão da companhia encarregada de defender a fronteira norte do país. Mas quem poderia chegar pelo norte, quando se é a cidade mais ao norte do mundo… ?\n\nPor fim, Elena Gromova, ginasta de Krasnov, dez vezes campeã nacional. Não, camaradas, nenhum parentesco com o presidente Gromov. A semelhança dos nomes é pura coincidência, como todas as semelhanças deste museu. Ela encarna sozinha a força e a graça da nossa bela nação.\n\nO esporte, camaradas, ensina o esforço, a disciplina e o respeito aos resultados oficiais.\n\nAlguma pergunta? Apenas históricas, por favor.",
    "f_salle_civils_intellectuels": "Eis a Sala dos artistas de Sovarka, camaradas. A criação aqui é livre, totalmente livre, dentro do quadro previsto para isso.\n\nAlexeï Mironov, poeta. Sua coletânea “Odes ao Plano Quinquenal” teve tiragem de dois milhões de exemplares, um para cada lar, e sua leitura foi tornada obrigatória. Nunca um poeta foi tão lido. Sua segunda coletânea, mais pessoal, nunca foi encontrada. Ele também não, aliás, durante alguns anos.\n\nA banda Severny Veter, “Vento do Norte”, a primeira banda de rock de Sovarka. O primeiro álbum foi proibido. O segundo também. O terceiro, “Hino ao Trator”, finalmente tocou na rádio do Estado. Os fãs da primeira hora nunca falam dele.\n\nViktor Roudenko, escultor de madeira e de gelo, com motosserra. Suas estátuas de gelo dos heróis da nação são de uma fidelidade impressionante, até a primavera. Era preciso recomeçar tudo a cada ano. O Estado viu nisso a mais bela metáfora da revolução permanente.\n\nSergueï Kravtsov, pintor. Dedicou a vida às paisagens de Sovarka: fábricas, chaminés, fumaça. Os críticos estrangeiros o acusavam de pintar sempre o mesmo quadro. É falso: ele pintou também a fumaça em tempo de neve.\n\nA arte, camaradas, eleva a alma do povo. Desde que não a eleve alto demais.\n\nAlguma pergunta? Apenas históricas, por favor.",
    "f_salle_grandes_villes": "Eis a Sala das grandes crises de Sovarka, camaradas. Um povo forte não esconde suas provações: ele as expõe, sob vidro, com uma iluminação caprichada.\n\nA fome dos anos vinte. Os historiadores estrangeiros falam de fome. Aqui, falamos de “período de sobriedade alimentar voluntária”. Na vitrine, o cartão de racionamento, o saco de farinha e o último pão da época. É autêntico. Ninguém teve coragem de comê-lo.\n\nA Grande Guerra. Nossos soldados combateram com uma coragem que o mundo inteiro nos inveja. Lembro que Sovarka nunca foi conquistada. As cidades em ruínas que vocês veem neste quadro foram reorganizadas de maneira estratégica pelo nosso estado-maior.\n\nA greve geral dos anos trinta. Os operários reivindicavam direitos para os trabalhadores. O Partido lhes deu total satisfação: a greve foi declarada ilegal, já que os trabalhadores estavam agora no poder. Contra quem eles teriam feito greve? Contra si mesmos?\n\nE, por fim, a mais dolorosa de todas: a final de 1937, perdida para El Estado. Naquele dia, a nação inteira chorou. Ainda hoje nosso coração sangra: Sovarka jamais se recuperará dessa derrota. Não esquecemos; apenas aprendemos a viver com essa ferida indelével. E olha que nosso árbitro tinha sido cuidadosamente escolhido. O deles também, infelizmente. A revanche nunca aconteceu: El Estado continua se recusando a jogar essa partida de novo. Devem estar com medo.\n\nAlguma pergunta? Apenas históricas, por favor. E, se possível, não sobre futebol.",
    "f_expositions_temporaires": "Eis a Sala das exposições rotativas, camaradas. Admirem. Não veem nada? É normal: a exposição anterior terminou e a próxima ainda não foi reservada. Alguns visitantes veem nela uma obra de arte por si só: “Vitrines vazias”, a única obra-prima de Sovarka que o Estado nunca precisou censurar. Se quiserem expor, dirijam-se à recepção."
  },
  "de": {
    "q_title": "Fragen an die Führerin",
    "q_intro": "Für 1 AP beantwortet Ouliana in diesem Saal drei Fragen (einmal am Tag).",
    "q_open": "Fragen stellen (1 AP)",
    "q_placeholder": "Ihre historische Frage …",
    "q_ask": "Fragen (noch {n})",
    "q_you": "Sie",
    "q_wait": "Ouliana überlegt …",
    "q_done": "Ouliana bittet Sie höflich, den Rundgang fortzusetzen.",
    "q_error": "Ouliana kann gerade nicht antworten. Es wurde keine Frage gezählt.",
    "q_r_pas_sur_place": "Sie müssen sich in einem Saal des Museums befinden.",
    "q_r_questions_epuisees": "Sie haben in diesem Saal heute bereits Ihre drei Fragen gestellt.",
    "q_r_dialogue_non_ouvert": "Öffnen Sie zuerst die Fragen (1 AP).",
    "q_r_pa_insuffisants": "Sie haben nicht genug AP.",
    "q_r_autre": "Der Server hat nicht bestätigt. Nichts wurde abgebucht.",
    "tGuide": "Ouliana Historiskaïa, offizielle Führerin",
    "listen": "Der Führerin zuhören",
    "f_hall": "Guten Tag und willkommen im Museum der Republik Sowarka, Genossen. Ich bin Ouliana Historiskaïa, offizielle Führerin des Museums, im Dienst der Geschichte. Der offiziellen Geschichte, versteht sich: Sie ist die einzige, die erhalten geblieben ist.\n\nDer Rundgang führt Sie von den großen Präsidenten zu den großen Parteien, von unseren Kriegshelden zu unseren Künstlern, ohne den Traktorismus, unsere Sportler und unsere großen Krisen zu vergessen. Ich rate Ihnen, der Reihenfolge des Rundgangs zu folgen. Nichts ist verboten, selbstverständlich. Es wird lediglich empfohlen, sehr nachdrücklich.\n\nFotografieren ist überall erlaubt, außer dort, wo es nicht erlaubt ist. Die Aufseher werden Sie darauf hinweisen.\n\nHaben Sie Fragen? Nur historische, bitte.",
    "f_salle_presidents": "Willkommen im Saal der Präsidenten, Genossen Besucher. Treten Sie näher, treten Sie näher.\n\nHier sehen Sie die fünf großen Führer, die Sowarka auf den Weg des Fortschritts geleitet haben.\n\nLinks Genosse Arkadi Iwanowitsch Solotow, erster Präsident unserer Republik. Er weihte den Präsidentenpalast ein. Dreißig Jahre lang beehrte er jede Eröffnung einer Fabrik, einer Brücke und einer Schule im Land mit seiner Anwesenheit. Kein Präsident hat im Dienst des Volkes so viele Bänder durchschnitten.\n\nEs folgt Taras Sergejewitsch Below. Ihm verdanken wir den berühmten Erlass über die Teestunde, der bis heute gilt. Ein Text von seltener Beständigkeit: nie angefochten, nie aufgehoben.\n\nGenosse Boris Nikolajewitsch Gromow wurde siebenmal wiedergewählt. Das Volk liebte ihn so sehr, dass er nicht einmal kandidieren musste.\n\nIhm folgte Wladimir Petrowitsch Lebedew. Ihnen fällt sicher die Ähnlichkeit mit seinem Vorgänger auf … Sie ist in der Tat verblüffend. Das Volk, das Genosse Gromow so sehr geliebt hatte, übertrug ganz selbstverständlich einen großen Teil seiner Zuneigung auf ihn. Lebedew war auch ein großer Verfechter des Dialogs zwischen den Institutionen: Sein Briefwechsel mit dem Volksrat wird im Archiv aufbewahrt … in dreifacher Ausfertigung.\n\nSchließlich Gennadi Andrejewitsch Sokolow. Ja, derselbe Kiefer, derselbe Blick. Die Wähler sahen darin das Zeichen einer bewundernswerten Kontinuität. Er schenkte dem Palast seinen silbernen Samowar, der bis heute die höchsten Beratungen des Staates wärmt.\n\nSelbstverständlich besteht keinerlei Verwandtschaft zwischen diesen drei großen Männern. Die Familiennamen beweisen es. Die Personenstandsregister jener Zeit wurden leider beim Brand des Archivs vernichtet, doch die offizielle Geschichtsschreibung ist eindeutig.\n\nUnd diese beiden leeren Rahmen, fragen Sie? Sie warten auf die künftigen Führer, die das Volk in seiner Weisheit wählen wird. Wer weiß … vielleicht einer von Ihnen?\n\nHaben Sie Fragen? Ich erinnere Sie daran, dass ich nur historische Fragen beantworte.",
    "f_salle_politiques": "Dies ist der Saal der siegreichen politischen Parteien. Bewundern Sie diese Banner: Jedes trägt das Gesicht eines gewählten Präsidenten, und hinter jedem Gesicht die große Partei, die ihn an die Macht gebracht hat.\n\nDenn ja, ein Präsident ist nur der bescheidene Vertreter der Partei, die ihn an die Macht gebracht hat, und die Partei selbst ist nur die bescheidene Struktur, die das souveräne Volk vertritt.\n\nBeginnen wir mit der Partei der Politischen Vorreiter. Sie führte unsere Nation aus der zaristischen Finsternis in das hochdemokratische Leben, das wir heute kennen. Hochdemokratisch, ja. Ich wäge meine Worte ab. Die Partei gab Sowarka seine ersten beiden Präsidenten, Genosse Solotow und Genosse Below. In der Vitrine sehen Sie das erste Parteibuch, die Feder, mit der die Verfassung unterzeichnet wurde, und ein Foto der ersten freien Wahl. Man erkennt sehr gut die Urne und den Parteivertreter, der für ihren Schutz sorgte.\n\nIn der Mitte die Partei des Glücklichen Proletariats, die Partei von Genosse Gromow. Ihr Programm passte in einen Satz: Das Proletariat ist glücklich. Die Studien jener Zeit bestätigten es zu hundert Prozent. Danach löste sich die Partei von selbst auf, da ihre Mission erfüllt war.\n\nSchließlich die Partei des Nostalgischen Fortschritts, die dem Land die Genossen Lebedew und Sokolow schenkte. Ihr Motto: „In die Vergangenheit voranschreiten, ohne je zurückzuweichen.“ Manche Länder nennen das „Moonwalk“, andere den estadischen Tango. Ihre Gegner, Verräter an der Nation, die umerzogen werden mussten, sagten, sie habe nichts Neues zu bieten. Genau das war ihr ganzes Programm.\n\nVielleicht fällt Ihnen auf, dass die Genossen Lebedew und Sokolow Genosse Gromow sehr ähnlich sehen, obwohl sie einer anderen Partei angehörten. Das beweist: Bei uns verhindert der Pluralismus die Kontinuität nicht.\n\nDiese drei großen Parteien haben eines gemeinsam: Sie haben jede Wahl gewonnen, zu der sie angetreten sind. Die anderen Parteien? Sie waren noch nicht bereit. Vielleicht sind sie es heute … Die Eintragungsregister liegen im Rathaus.\n\nHaben Sie Fragen? Nur historische, bitte.",
    "f_salle_honneur_militaire_nationale": "Treten Sie näher, Genossen. Sie betreten den Saal der militärischen Ehren. Hier erzählt jede Medaille von einem Sieg, und jeder Sieg wurde vom Ministerium für die Verteidigung des Vaterlandes ordnungsgemäß beglaubigt.\n\nIn der großen Vitrine die Paradeuniform des ersten Kommandanten der Volksarmee. Sie trägt siebenundvierzig Medaillen: fast fünfzehn Kilo Metall. Die Historiker sind sich einig, dass er sie alle verdient hat, auch jene, die er sich selbst verliehen hat. Beim Attentat von Krasnow retteten sie ihm das Leben: Die Kugel, mitten aufs Herz abgefeuert, zerschellte an ihnen und verursachte nur einen leichten Bluterguss.\n\nAn dieser Wand die Karte der Großen Verteidigung des Nordens. Unsere Soldaten hielten dort elf Winter lang ihre Stellungen gegen einen Feind, der mangels Dokumenten bis heute unbekannt ist. Er ist nie gekommen: der Beweis, dass die Verteidigung vollkommen war. Beachten Sie übrigens, dass Sowarka nie erobert wurde. Darauf ist das Land besonders stolz.\n\nDieser verbeulte Helm gehörte dem Soldaten Pjotr Newijew, Held der Nation. Er überquerte als Erster den zugefrorenen Fluss beim Marsch von 1924. Der Zweite war sein Kommandant, der sichergehen wollte, dass das Eis hielt.\n\nBeachten Sie schließlich das Ehrenbuch der Wehrpflichtigen. Jeder einberufene Bürger trägt dort voller Stolz seinen Namen ein. Wer sich nicht eingetragen hat, steht in einem anderen Register, das anderswo aufbewahrt wird.\n\nHaben Sie Fragen? Nur historische, bitte.",
    "f_salle_organisations": "Willkommen im Saal des Traktorismus, Genossen. Sie befinden sich im Herzen der Seele Sowarkas.\n\nDer Traktorismus ist kein Aberglaube: Er ist eine wissenschaftliche Religion. Er lehrt, dass der Kollektive Traktor die Felder pflügt, wie er die Gewissen pflügt, in gerader Linie und ohne je zurückzuweichen. Und in einem gut gepflügten Gewissen keimen die Samen der Freiheit und der Emanzipation am Ende immer.\n\nIn dieser Vitrine die Heilige Zündkerze, unversehrt im ersten Traktor der Kolchose von Krasnow gefunden. Ihr werden zahlreiche Wunder zugeschrieben. Das bekannteste ist das des Winters 1931: Der Traktor sprang beim ersten Versuch an.\n\nAn dieser Wand die Zehn Gebote der Wartung. Das erste: „Du sollst alle fünftausend Kilometer das Öl wechseln.“ Das zehnte: „Du sollst nicht begehren deines Nächsten Traktor, denn alle Traktoren gehören dem Volk.“\n\nBeachten Sie diese liturgischen Gewänder: die blaue Latzhose der hohen Feste und den Arbeitsanzug der gewöhnlichen Tage. Genosse Pontifex Traktorenko trägt sie noch heute bei der Segnung der Motoren, jeden Frühling, in der Großen Kirche.\n\nStaat und Traktorismus sind selbstverständlich vollkommen getrennt. Es kommt nur vor, dass sie im selben Moment dasselbe denken.\n\nHaben Sie Fragen? Nur historische, bitte.",
    "f_salle_artistes_sportifs": "Dies ist der Saal der Sportler Sowarkas, Genossen. Hier werden jene gefeiert, die unsere Farben hochgehalten haben, in Nowomirsk, Krasnow und Starowka.\n\nIgor Sedow, Fußballer aus Nowomirsk. Der größte Torjäger in der Geschichte der Landesmeisterschaft. Er war unaufhaltsam, besonders in der dritten Halbzeit. Er war berühmt dafür, jedes Tor mit einer Flasche Wodka auf ex zu feiern. Er hat nie mehr als 3 Tore pro Spiel erzielt, was einiges erklärt ...\n\nArvydas Tkatchenko, Basketballspieler aus Krasnow, war ein wahrer Koloss. Mit 12 Jahren vom Trainer der Stadt entdeckt, als er im Wald von Krasnow, wo er Holzfäller war, mit bloßen Händen gegen Bären kämpfte, hatte er schwierige Anfänge als Basketballer … für die Basketballbretter, die wegen seiner zerstörerischen Dunks eigens verstärkt werden mussten. Er ist das Symbol sowarkischer Stärke.\n\nAndrei Wolkow, Stabhochspringer aus Nowomirsk, wurde der Vogel genannt. Mit seinem Stab setzte er die Gesetze der Schwerkraft außer Kraft. Der Legende nach fror ihm ein Zeh ab, nach einem Sprung, der ihn in die Stratosphäre katapultierte. Ein Unfall mit einem Satelliten beendete seine Karriere vorzeitig. Andrei ist der einzige Mensch auf der Welt, für den „Sky is not the limit“ gilt.\n\nBatyr Nourbaïev, Biathlet aus Starowka, war zum Champion bestimmt. Als Bauernsohn begleitete er die Rentierherden auf Skiern und musste sie gegen Wölfe und Eisbären verteidigen. Seine außergewöhnlichen Fähigkeiten brachten ihm die Einberufung in die Armee Sowarkas ein, wo er zum Hauptmann der Kompanie ernannt wurde, die die Nordgrenze des Landes verteidigt. Aber wer sollte schon von Norden kommen, wenn man die nördlichste Stadt der Welt ist … ?\n\nSchließlich Elena Gromowa, Turnerin aus Krasnow, zehnfache Landesmeisterin. Nein, Genossen, keine Verwandtschaft mit Präsident Gromow. Die Ähnlichkeit der Namen ist reiner Zufall, wie alle Ähnlichkeiten in diesem Museum. Sie allein verkörpert die Kraft und Anmut unserer schönen Nation.\n\nDer Sport, Genossen, lehrt Anstrengung, Disziplin und den Respekt vor den offiziellen Ergebnissen.\n\nHaben Sie Fragen? Nur historische, bitte.",
    "f_salle_civils_intellectuels": "Dies ist der Saal der Künstler Sowarkas, Genossen. Das Schaffen ist hier frei, völlig frei, im dafür vorgesehenen Rahmen.\n\nAlexei Mironow, Dichter. Sein Band „Oden an den Fünfjahresplan“ erschien in zwei Millionen Exemplaren, eines für jeden Haushalt, und seine Lektüre wurde zur Pflicht. Nie wurde ein Dichter so viel gelesen. Sein zweiter, persönlicherer Band wurde nie gefunden. Er selbst übrigens auch nicht, einige Jahre lang.\n\nDie Band Sewerny Weter, „Nordwind“, die erste Rockband Sowarkas. Ihr erstes Album wurde verboten. Das zweite auch. Das dritte, „Hymne an den Traktor“, lief endlich im Staatsrundfunk. Die Fans der ersten Stunde sprechen nie darüber.\n\nViktor Rudenko, Bildhauer in Holz und Eis, mit der Kettensäge. Seine Eisstatuen der Helden der Nation sind von verblüffender Treue, bis zum Frühling. Jedes Jahr musste alles von vorn beginnen. Der Staat sah darin die schönste Metapher der permanenten Revolution.\n\nSergei Krawzow, Maler. Er widmete sein Leben den Landschaften Sowarkas: Fabriken, Schornsteine, Rauch. Ausländische Kritiker warfen ihm vor, immer dasselbe Bild zu malen. Das ist falsch: Er malte auch den Rauch bei Schnee.\n\nDie Kunst, Genossen, erhebt die Seele des Volkes. Solange sie sie nicht zu hoch erhebt.\n\nHaben Sie Fragen? Nur historische, bitte.",
    "f_salle_grandes_villes": "Dies ist der Saal der großen Krisen Sowarkas, Genossen. Ein starkes Volk verbirgt seine Prüfungen nicht: Es stellt sie aus, unter Glas, sorgfältig beleuchtet.\n\nDie Hungersnot der Zwanzigerjahre. Ausländische Historiker sprechen von Hungersnot. Bei uns spricht man von einer „Periode freiwilliger Ernährungsmäßigung“. In der Vitrine die Lebensmittelkarte, der Mehlsack und das letzte Brot jener Zeit. Es ist echt. Niemand hat gewagt, es zu essen.\n\nDer Große Krieg. Unsere Soldaten kämpften mit einem Mut, um den uns die ganze Welt beneidet. Ich erinnere Sie daran, dass Sowarka nie erobert wurde. Die zerstörten Städte, die Sie auf diesem Gemälde sehen, wurden von unserem Generalstab strategisch neu geordnet.\n\nDer Generalstreik der Dreißigerjahre. Die Arbeiter forderten Rechte für die Arbeiter. Die Partei gab ihnen volle Genugtuung: Der Streik wurde für illegal erklärt, da die Arbeiter nun an der Macht waren. Gegen wen hätten sie streiken sollen? Gegen sich selbst?\n\nUnd schließlich die schmerzlichste von allen: das Finale von 1937, verloren gegen El Estado. An jenem Tag weinte die ganze Nation. Noch heute blutet unser Herz: Nie wird Sowarka sich von dieser Niederlage erholen. Man vergisst nicht, man lernt nur, mit dieser unauslöschlichen Wunde zu leben. Dabei war unser Schiedsrichter sorgfältig ausgewählt worden. Ihrer leider auch. Die Revanche hat nie stattgefunden: El Estado weigert sich bis heute, das Spiel zu wiederholen. Sie haben wohl Angst.\n\nHaben Sie Fragen? Nur historische, bitte. Und wenn möglich nicht über Fußball.",
    "f_expositions_temporaires": "Dies ist der Saal der Wechselausstellungen, Genossen. Bewundern Sie. Sie sehen nichts? Das ist normal: Die vorige Ausstellung ist vorbei, und die nächste wurde noch nicht gebucht. Manche Besucher sehen darin ein eigenständiges Kunstwerk: „Leere Vitrinen“, das einzige Meisterwerk Sowarkas, das der Staat nie zensieren musste. Wenn Sie ausstellen möchten, wenden Sie sich an den Empfang."
  }
};
for(const [lang,labels] of Object.entries(texts))
  if(global.RP_I18N_RESOURCES?.[lang]?.translation)
    global.RP_I18N_RESOURCES[lang].translation.guideMuseeNovomirsk={...labels};
function text(key,vars={}){
  const original=texts.fr[key];
  if(typeof original!=='string')return '';
  const locale=global.RP_I18N_GAME_ENABLED===true ? global.RPPlateauI18n?.language?.()||'fr' : 'fr';
  const template=texts[locale]?.[key]||original;
  return template.replace(/\{(\w+)\}/g,(full,k)=>Object.hasOwn(vars,k)?String(vars[k]):full);
}
global.RPGuideMuseeNovomirskI18n=Object.freeze({text,langues:Object.freeze(Object.keys(texts)),cles:Object.freeze(Object.keys(texts.fr))});
global.texteGuideMusee=text;
})(typeof window!=='undefined'?window:globalThis);
